insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('d0000000-0000-0000-0000-000000000001', 'mrcp2', '2ebe3b03-4042-4b85-ba76-83d16816f645',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('d0000000-0000-0000-0000-000000000001', 'A', 'Administer intravenous thrombolysis', false, 'Ruled out because thrombolysis is not appropriate after recent PCI; the patient needs urgent invasive reassessment of the stent and coronary anatomy, and thrombolytic therapy carries bleeding risk without addressing the underlying mechanical problem (stent thrombosis) as effectively as repeat PCI.', 1),
('d0000000-0000-0000-0000-000000000001', 'B', 'Arrange urgent pericardiocentesis for the pericardial effusion', false, 'Ruled out because the effusion is small and there are no tamponade features (no pulsus paradoxus, no significant haemodynamic compromise attributable to tamponade); the hypotension and ECG changes are best explained by recurrent infarction/stent thrombosis, which is the priority to address.', 2),
('d0000000-0000-0000-0000-000000000001', 'C', 'Start a heparin infusion and observe with serial troponins', false, 'Ruled out because this delays definitive treatment; new ST elevation with haemodynamic compromise after PCI mandates immediate catheter laboratory activation rather than a watchful waiting strategy with serial biomarkers.', 3),
('d0000000-0000-0000-0000-000000000001', 'D', 'Urgent repeat coronary angiography to assess for acute stent thrombosis', true, 'Correct. Recurrent chest pain with new ST elevation in the same territory after primary PCI, especially with haemodynamic compromise, is highly suggestive of acute/subacute stent thrombosis until proven otherwise. This is a medical emergency requiring immediate repeat angiography with a view to further intervention (thrombus aspiration, balloon angioplasty, or re-stenting), not observation or non-invasive testing.', 4),
('d0000000-0000-0000-0000-000000000001', 'E', 'Perform urgent CT pulmonary angiography to exclude pulmonary embolism', false, 'Ruled out because the clinical picture (recurrent pain, ST elevation in the same territory as the prior culprit vessel) is far more consistent with stent thrombosis than PE, and pursuing CTPA would dangerously delay definitive coronary intervention.', 5),
('d0000000-0000-0000-0000-000000000002', 'A', 'Continue fondaparinux alone throughout the angiogram and any subsequent PCI', false, 'Ruled out because fondaparinux monotherapy during catheterisation is associated with an increased risk of catheter-related thrombus; additional periprocedural anticoagulation (unfractionated heparin bolus) is required.', 1),
('d0000000-0000-0000-0000-000000000002', 'B', 'Add unfractionated heparin as a single bolus at the time of catheterisation, in addition to fondaparinux', true, 'Correct. Fondaparinux is associated with a lower bleeding risk than heparin in NSTEACS, including in renal impairment, and is guideline-preferred in this context; however, it is associated with catheter thrombosis when used alone during PCI, so current guidance recommends adding a single bolus of unfractionated heparin (or bivalirudin) to cover the procedure itself.', 2),
('d0000000-0000-0000-0000-000000000002', 'C', 'Switch to a full treatment-dose low molecular weight heparin (enoxaparin) infusion', false, 'Ruled out because enoxaparin is renally cleared and accumulates significantly in severe CKD (eGFR 22), increasing bleeding risk; it is not the preferred agent here, and switching between different anticoagulant classes (fondaparinux to LMWH) around PCI increases bleeding risk further.', 3),
('d0000000-0000-0000-0000-000000000002', 'D', 'Stop all anticoagulation prior to angiography given the bleeding risk from renal impairment', false, 'Ruled out because anticoagulation remains indicated in NSTEACS irrespective of renal impairment (with dose/agent adjustment where needed); stopping anticoagulation entirely would leave the patient inadequately protected against thrombotic complications while awaiting/undergoing angiography.', 4),
('d0000000-0000-0000-0000-000000000002', 'E', 'Start a therapeutic dose of a direct oral anticoagulant (e.g. apixaban) as periprocedural cover', false, 'Ruled out because DOACs are not used as periprocedural anticoagulation for PCI in ACS; parenteral anticoagulants (heparin, bivalirudin, fondaparinux) are the standard of care during the procedure.', 5),
('d0000000-0000-0000-0000-000000000003', 'A', '12 months, with review of bleeding risk to consider de-escalation or extension thereafter', true, 'Correct. Standard guideline recommendation after ACS treated with PCI and drug-eluting stent implantation is 12 months of dual antiplatelet therapy in patients without excessive bleeding risk, with individualised decisions thereafter (e.g. continuing a single antiplatelet long-term, or extending DAPT/considering a reduced-dose regimen in selected high ischaemic-risk, low bleeding-risk patients).', 1),
('d0000000-0000-0000-0000-000000000003', 'B', '1 month, then aspirin monotherapy indefinitely', false, 'Ruled out because 1 month of DAPT is inadequate after ACS with stent implantation; this abbreviated duration is reserved for patients at very high bleeding risk, which is not described here.', 2),
('d0000000-0000-0000-0000-000000000003', 'C', 'Lifelong dual antiplatelet therapy with no plan to ever stop either agent', false, 'Ruled out because lifelong DAPT is not standard practice; it carries an unnecessarily high long-term bleeding risk without added ischaemic benefit beyond the recommended duration in most patients.', 3),
('d0000000-0000-0000-0000-000000000003', 'D', '3 months, then switch to ticagrelor monotherapy', false, 'Ruled out because while ticagrelor monotherapy after a short DAPT period is an evidence-based strategy in some high-bleeding-risk populations, it is not the standard default duration for this lower-bleeding-risk patient with standard ACS; 12 months of DAPT remains the default recommendation.', 4),
('d0000000-0000-0000-0000-000000000003', 'E', '6 weeks, matching the duration used after balloon angioplasty without stenting', false, 'Ruled out because this patient received a drug-eluting stent, which requires a substantially longer duration of DAPT than plain balloon angioplasty to reduce the risk of stent thrombosis.', 5),
('d0000000-0000-0000-0000-000000000004', 'A', 'IV glyceryl trinitrate infusion to reduce afterload and improve forward flow', false, 'Ruled out because nitrates are contraindicated in RV infarction/RV-dependent hypotension; by reducing venous return (preload), they can cause profound hypotension in a preload-dependent RV-failure state.', 1),
('d0000000-0000-0000-0000-000000000004', 'B', 'IV furosemide to relieve venous congestion and improve RV function', false, 'Ruled out because diuretics reduce preload, which is detrimental in RV infarction where cardiac output depends on maintaining adequate RV filling pressures; this would worsen hypotension.', 2),
('d0000000-0000-0000-0000-000000000004', 'C', 'Immediate initiation of a beta-blocker to reduce myocardial oxygen demand', false, 'Ruled out because beta-blockade would worsen the complete heart block and further depress the already compromised junctional escape rhythm and cardiac output; it is contraindicated in this acute setting.', 3),
('d0000000-0000-0000-0000-000000000004', 'D', 'High-dose IV morphine to control chest pain as the immediate priority', false, 'Ruled out because while analgesia is important, the immediate priority in a hypotensive, preload-dependent RV infarction is haemodynamic support with fluids and pacing; morphine can also cause venodilation and worsen hypotension in this context.', 4),
('d0000000-0000-0000-0000-000000000004', 'E', 'IV fluid bolus to optimise right ventricular preload, avoiding nitrates and other venodilators', true, 'Correct. In right ventricular infarction, cardiac output is highly preload-dependent because the RV is poorly contractile; hypotension should be managed with judicious IV fluid loading to augment RV preload, while nitrates, diuretics and other venodilators are avoided as they can precipitate severe hypotension by reducing preload further.', 5),
('d0000000-0000-0000-0000-000000000005', 'A', 'Manage the RCA lesion medically only, as intervention on non-culprit vessels during the STEMI admission increases mortality', false, 'Ruled out because trial evidence demonstrates a reduction, not an increase, in adverse cardiovascular outcomes with complete revascularisation in stable patients; a culprit-only strategy is now considered suboptimal for patients with amenable non-culprit disease.', 1),
('d0000000-0000-0000-0000-000000000005', 'B', 'Perform emergency PCI to the RCA lesion simultaneously with the culprit LAD, regardless of haemodynamic status, due to cardiogenic shock risk', false, 'Ruled out because in the absence of cardiogenic shock, immediate multivessel PCI is not mandatory; complete revascularisation may be performed during the index procedure or staged, and in cardiogenic shock specifically, culprit-lesion-only PCI is actually preferred (per CULPRIT-SHOCK).', 2),
('d0000000-0000-0000-0000-000000000005', 'C', 'Plan complete revascularisation with PCI to the non-culprit RCA lesion, either during the index admission or as a staged procedure within 45 days', true, 'Correct. Current evidence (e.g. COMPLETE trial) supports complete revascularisation of significant non-culprit lesions in haemodynamically stable STEMI patients, either immediately or as a staged procedure, as this reduces the risk of future cardiovascular death or myocardial infarction compared with a culprit-lesion-only strategy.', 3),
('d0000000-0000-0000-0000-000000000005', 'D', 'Arrange CABG for the RCA lesion as the only evidence-based option in multivessel disease post-STEMI', false, 'Ruled out because PCI to non-culprit lesions (staged or immediate) is supported by trial evidence as an appropriate revascularisation strategy in this setting; CABG is not mandated for a single moderate non-culprit lesion of this nature.', 4),
('d0000000-0000-0000-0000-000000000005', 'E', 'No further intervention or investigation of the RCA lesion is required as it is not the culprit vessel', false, 'Ruled out because ignoring a significant non-culprit lesion is inconsistent with current evidence favouring complete revascularisation to reduce future ischaemic events.', 5),
('d0000000-0000-0000-0000-000000000006', 'A', 'Supportive management with heart failure therapy (e.g. ACE inhibitor and beta-blocker) as tolerated, and follow-up imaging to confirm resolution of LV function', true, 'Correct. This presentation (angiographically normal coronaries, apical ballooning with basal hyperkinesis, precipitated by emotional stress) is classic for Takotsubo (stress) cardiomyopathy. Management is supportive, mirroring heart failure treatment for the acute phase (ACE inhibitors, beta-blockers as tolerated, diuretics if congested), with follow-up echocardiography as LV function typically recovers over weeks.', 1),
('d0000000-0000-0000-0000-000000000006', 'B', 'Immediate referral for CABG given the extent of ST elevation and troponin rise', false, 'Ruled out because there is no obstructive coronary disease to revascularise; CABG has no role in Takotsubo cardiomyopathy.', 2),
('d0000000-0000-0000-0000-000000000006', 'C', 'Long-term dual antiplatelet therapy as for an atherosclerotic ACS', false, 'Ruled out because in the absence of obstructive coronary disease or intervention, long-term DAPT is not indicated; this is not an atherothrombotic event.', 3),
('d0000000-0000-0000-0000-000000000006', 'D', 'Urgent endomyocardial biopsy to confirm the diagnosis before starting any treatment', false, 'Ruled out because Takotsubo cardiomyopathy is a clinical/imaging diagnosis (characteristic wall motion pattern with unobstructed coronaries, often after emotional/physical stress); biopsy is not routinely required and would delay appropriate supportive treatment.', 4),
('d0000000-0000-0000-0000-000000000006', 'E', 'Reassure the patient that no follow-up is needed as this is a benign, self-limiting condition with no complications', false, 'Ruled out because although LV function often recovers, Takotsubo cardiomyopathy carries risk of acute complications (heart failure, arrhythmia, LV outflow obstruction, thrombus, and rarely death) and recurrence; follow-up is required, not simple reassurance without review.', 5),
('d0000000-0000-0000-0000-000000000007', 'A', 'Add amiodarone for further rate control', false, 'Ruled out because while amiodarone can be used for rate control, it is not the preferred next step here given his LVEF and the failure of first-line agents; AV node ablation and pacing is a more definitive, guideline-supported strategy for refractory rate control in this context, and amiodarone carries significant long-term toxicity.', 1),
('d0000000-0000-0000-0000-000000000007', 'B', 'Attempt electrical cardioversion to restore sinus rhythm', false, 'Ruled out because this is permanent AF (a rhythm-control strategy has already been foregone/is not appropriate), and cardioversion is not expected to be durable or is not the established strategy in permanent AF; the issue here is rate control failure, best addressed with AV node ablation and pacing.', 2),
('d0000000-0000-0000-0000-000000000007', 'C', 'Refer for atrioventricular node ablation with permanent pacemaker/CRT implantation', true, $x$Correct. In patients with permanent AF and uncontrolled ventricular rate despite optimised pharmacological rate control (beta-blocker plus digoxin), particularly with evidence of tachycardia-mediated/rate-related cardiomyopathy, AV node ablation with implantation of a permanent pacemaker (biventricular/CRT device given the reduced LVEF) provides reliable rate control ('pace and ablate' strategy) and can improve symptoms and ventricular function.$x$, 3),
('d0000000-0000-0000-0000-000000000007', 'D', 'Increase the digoxin dose further to achieve better rate control', false, 'Ruled out because digoxin is already at a therapeutic level; increasing the dose risks toxicity without reliably achieving better rate control, particularly during exertion, and would not be expected to solve persistent rapid rates.', 4),
('d0000000-0000-0000-0000-000000000007', 'E', 'Discontinue beta-blockade and rely on digoxin monotherapy for rate control', false, 'Ruled out because stopping beta-blockade would likely worsen rate control, not improve it; combination pharmacological therapy has already failed, indicating a need for a non-pharmacological strategy.', 5),
('d0000000-0000-0000-0000-000000000008', 'A', 'Long-term flecainide therapy as first-line management', false, $x$Ruled out because catheter ablation is preferred as definitive first-line therapy for symptomatic AVNRT, particularly given the patient's preference to avoid long-term medication; flecainide is a pharmacological option but not first-line when ablation is available and desired.$x$, 1),
('d0000000-0000-0000-0000-000000000008', 'B', 'Electrophysiological study with catheter ablation of the slow pathway', true, $x$Correct. The ECG findings (pseudo-R' in V1, pseudo-S in inferior leads representing the retrograde P wave buried in the QRS) combined with adenosine-responsive regular narrow-complex tachycardia are classic for AVNRT. Catheter ablation of the slow pathway is the definitive, first-line curative treatment for symptomatic, recurrent AVNRT, with high success rates and low complication risk, and avoids the need for long-term antiarrhythmic medication.$x$, 2),
('d0000000-0000-0000-0000-000000000008', 'C', 'Permanent pacemaker implantation to prevent recurrence', false, 'Ruled out because AVNRT is a re-entrant tachycardia not related to bradycardia or conduction disease requiring pacing; a pacemaker has no role in its management.', 3),
('d0000000-0000-0000-0000-000000000008', 'D', 'Reassurance only, as AVNRT is always self-limiting and does not require further treatment', false, 'Ruled out because although AVNRT is not typically life-threatening, recurrent symptomatic episodes warrant active treatment; simple reassurance without addressing recurrence is inappropriate when a curative option (ablation) exists.', 4),
('d0000000-0000-0000-0000-000000000008', 'E', 'DC cardioversion as the definitive long-term treatment', false, 'Ruled out because DC cardioversion is a treatment for the acute episode if pharmacological measures fail, not a definitive long-term strategy to prevent recurrence; catheter ablation addresses the underlying substrate.', 5),
('d0000000-0000-0000-0000-000000000009', 'A', 'Deactivate the ICD to prevent further painful shocks', false, 'Ruled out because deactivating the ICD would remove life-saving therapy for recurrent VT and risk sudden cardiac death; the priority is to treat the underlying arrhythmia (with ablation, sedation, and optimised antiarrhythmic therapy), not to disable protection.', 1),
('d0000000-0000-0000-0000-000000000009', 'B', 'Increase the bisoprolol dose beyond the maximally tolerated level', false, 'Ruled out because the beta-blocker is already at maximally tolerated dose; further uptitration risks haemodynamic compromise (hypotension, bradycardia) without reliably controlling the arrhythmia, and would not address the underlying substrate.', 2),
('d0000000-0000-0000-0000-000000000009', 'C', 'Discontinue amiodarone and switch to sotalol', false, 'Ruled out because sotalol has proarrhythmic risk (QT prolongation, torsades) and is generally less effective than amiodarone for VT suppression in structural heart disease; the described refractory storm should prompt escalation to ablation, not a drug switch of this nature.', 3),
('d0000000-0000-0000-0000-000000000009', 'D', 'Arrange elective outpatient cardiac MRI before considering further intervention', false, 'Ruled out because this is an emergency (electrical storm) requiring urgent inpatient management; elective outpatient imaging would dangerously delay definitive treatment.', 4),
('d0000000-0000-0000-0000-000000000009', 'E', 'Urgent referral for catheter ablation of the VT circuit', true, 'Correct. Electrical storm (≥3 episodes of sustained VT/VF or appropriate ICD therapies within 24 hours) refractory to antiarrhythmic drug therapy (beta-blockade plus amiodarone) is an indication for urgent catheter ablation to target and eliminate the arrhythmogenic substrate, which reduces further VT recurrence and improves outcomes when drug therapy alone is failing.', 5),
('d0000000-0000-0000-0000-000000000010', 'A', 'Bridge with therapeutic-dose low molecular weight heparin while apixaban is withheld', false, 'Ruled out because heparin bridging is not indicated when interrupting DOAC therapy (unlike vitamin K antagonists); bridging in this context increases bleeding risk without a clear benefit, since DOACs have a rapid offset and onset of action.', 1),
('d0000000-0000-0000-0000-000000000010', 'B', 'Continue apixaban throughout the perioperative period without interruption', false, 'Ruled out because continuing full-dose anticoagulation through a procedure with standard/significant bleeding risk (laparoscopic cholecystectomy) would unacceptably increase perioperative bleeding risk; interruption is required.', 2),
('d0000000-0000-0000-0000-000000000010', 'C', 'Stop apixaban 7 days before surgery and check anti-Xa levels prior to proceeding', false, 'Ruled out because a 7-day interruption is excessive for apixaban (a shorter, drug-specific interval based on half-life and renal function is appropriate) and would leave the patient unnecessarily unprotected against thromboembolism for longer than needed; anti-Xa monitoring is not routinely required for standard elective interruption.', 3),
('d0000000-0000-0000-0000-000000000010', 'D', 'Omit apixaban for approximately 48 hours before surgery and resume 24-48 hours after, without heparin bridging', true, $x$Correct. For standard-risk procedures in patients on a DOAC with normal renal function, current guidance recommends simple interruption of the DOAC for an appropriate interval based on the drug's half-life and procedural bleeding risk (typically around 48 hours before a standard/high-bleeding-risk procedure for apixaban), resuming post-operatively once haemostasis is adequate. Heparin bridging is not required with DOACs, unlike with warfarin, because of their rapid onset/offset.$x$, 4),
('d0000000-0000-0000-0000-000000000010', 'E', 'Switch to warfarin with bridging heparin in the weeks prior to surgery', false, 'Ruled out because switching to warfarin introduces unnecessary complexity, delay, and bridging-related bleeding risk when simple, well-established DOAC interruption protocols exist for elective surgery.', 5),
('d0000000-0000-0000-0000-000000000011', 'A', 'Reassure the patient that this ECG pattern is a normal variant requiring no further action', false, 'Ruled out because a spontaneous type 1 Brugada pattern with syncope and a strong family history of sudden death is a high-risk finding, not a benign variant, and requires further risk stratification and likely ICD implantation.', 1),
('d0000000-0000-0000-0000-000000000011', 'B', 'Start a beta-blocker as first-line therapy to prevent sudden cardiac death', false, 'Ruled out because beta-blockers are not established first-line therapy for primary prevention of sudden death in Brugada syndrome; ICD implantation is the evidence-based intervention in high-risk patients, and some agents (certain beta-blockers) have limited specific evidence in this condition.', 2),
('d0000000-0000-0000-0000-000000000011', 'C', 'Arrange elective DC cardioversion given the ECG abnormality', false, 'Ruled out because there is no arrhythmia present requiring cardioversion; the ECG shows a repolarisation pattern associated with arrhythmic risk, not a current tachyarrhythmia.', 3),
('d0000000-0000-0000-0000-000000000011', 'D', 'Perform genetic testing alone and defer any device therapy pending results', false, 'Ruled out because while genetic testing (e.g. SCN5A) can be useful for family screening, it should not delay ICD consideration in a patient who already meets high-risk clinical criteria (syncope, spontaneous type 1 pattern, family history of sudden death).', 4),
('d0000000-0000-0000-0000-000000000011', 'E', 'Refer for electrophysiological risk stratification and ICD implantation given syncope with a spontaneous type 1 Brugada pattern and family history of sudden death', true, 'Correct. This presentation (spontaneous coved-type/type 1 Brugada ECG pattern, syncope, and a family history of sudden cardiac death) places this patient in a high-risk category for ventricular arrhythmia. Current guidance supports ICD implantation in Brugada syndrome patients with a spontaneous type 1 pattern and syncope of likely arrhythmic origin, given the elevated risk of sudden cardiac death, often after further risk stratification (e.g. electrophysiological study, though the ECG/history alone in this scenario is a class I/IIa indication depending on guideline).', 5),
('d0000000-0000-0000-0000-000000000012', 'A', 'This represents new ventricular tachycardia unrelated to flecainide use', false, 'Ruled out because the described sawtooth appearance with regular 1:1 conduction in a patient recently started on a class Ic agent is the classic description of flecainide-induced atrial flutter with 1:1 conduction, not primary VT, especially in a structurally normal heart.', 1),
('d0000000-0000-0000-0000-000000000012', 'B', $x$Flecainide has organised the atrial fibrillation into atrial flutter, which is now conducting 1:1 due to slowed atrial rate and flecainide's effect on the AV node; flecainide should not be used as monotherapy for atrial flutter and an AV nodal blocking agent or catheter ablation should be considered$x$, true, $x$Correct. Class Ic agents like flecainide can 'organise' AF into a slower, more homogeneous atrial flutter; because the atrial rate is slowed, AV nodal conduction can then occur 1:1 (rather than the usual 2:1 block seen with typical flutter at ~300 bpm), producing a rapid, dangerous broad-complex tachycardia. This is a recognised hazard of flecainide, and management should include avoiding flecainide monotherapy for atrial flutter (combining with an AV nodal blocker if used, or preferably referring for catheter ablation of the flutter circuit).$x$, 2),
('d0000000-0000-0000-0000-000000000012', 'C', 'This is an expected and safe effect of flecainide requiring no change in management', false, 'Ruled out because 1:1 AV conduction with flecainide-induced flutter is a dangerous, recognised complication that can cause haemodynamic compromise, and management must change (avoid flecainide monotherapy, add AV nodal blockade or pursue ablation).', 3),
('d0000000-0000-0000-0000-000000000012', 'D', 'Flecainide should be increased in dose to better suppress the atrial arrhythmia', false, 'Ruled out because increasing flecainide dose does not address the mechanism of 1:1 conduction and class Ic agents can have proarrhythmic effects at higher doses; this would not be a safe response to this presentation.', 4),
('d0000000-0000-0000-0000-000000000012', 'E', 'This indicates flecainide toxicity from renal impairment and simply requires dose reduction with no other action', false, 'Ruled out because the mechanism described is pharmacodynamic (atrial flutter organisation with 1:1 conduction), not primarily a toxicity/accumulation issue; the key action is addressing the flutter risk (AV nodal blockade or ablation), not just dose adjustment.', 5),
('d0000000-0000-0000-0000-000000000013', 'A', 'Refer for cardiac resynchronisation therapy (CRT)', true, 'Correct. This patient has symptomatic HFrEF despite optimal guideline-directed quadruple medical therapy, in sinus rhythm, with a markedly prolonged QRS (>150ms) and LBBB morphology — the group shown to derive the greatest benefit from CRT in terms of symptoms, hospitalisation and mortality. CRT is therefore the appropriate next step.', 1),
('d0000000-0000-0000-0000-000000000013', 'B', 'Add ivabradine given his persistent symptoms', false, $x$Ruled out because ivabradine's role is in patients with heart rate ≥70bpm in sinus rhythm despite maximally tolerated beta-blockade; this patient's heart rate is 68bpm, so ivabradine would not be indicated, and his QRS/LBBB findings point clearly towards a CRT indication instead.$x$, 2),
('d0000000-0000-0000-0000-000000000013', 'C', 'Increase spironolactone dose beyond standard target to improve symptom control', false, 'Ruled out because spironolactone is already at an appropriate dose for heart failure (25mg), and further increases would raise hyperkalaemia risk without an evidence base for improved outcomes; his most impactful next step is addressing his electrical dyssynchrony with CRT.', 3),
('d0000000-0000-0000-0000-000000000013', 'D', 'Refer for heart transplantation assessment as the next step', false, 'Ruled out because transplantation assessment is reserved for advanced, refractory heart failure after exhausting other options including device therapy (CRT, ICD) and optimal medical therapy; it is premature here when CRT has not yet been tried.', 4),
('d0000000-0000-0000-0000-000000000013', 'E', 'Switch sacubitril-valsartan back to an ACE inhibitor given his QRS prolongation', false, 'Ruled out because there is no indication to de-escalate from sacubitril-valsartan to an ACE inhibitor based on QRS duration; sacubitril-valsartan should be continued as part of optimal quadruple therapy, and the QRS finding is instead an indication for CRT.', 5),
('d0000000-0000-0000-0000-000000000014', 'A', 'Stop dapagliflozin during the acute admission and only restart it after 6 weeks of stability', false, 'Ruled out because current evidence supports continuing (or even initiating) SGLT2 inhibitors during hospitalisation for decompensated heart failure rather than withholding them, provided there is no contraindication such as significant AKI or ketoacidosis risk.', 1),
('d0000000-0000-0000-0000-000000000014', 'B', 'Stop dapagliflozin permanently due to the risk of euglycaemic ketoacidosis in acute illness', false, $x$Ruled out because permanent discontinuation is not warranted; while transient interruption may be considered during severe acute illness or risk of ketoacidosis (e.g. peri-surgery, severe intercurrent illness with reduced oral intake), this patient's presentation does not describe such risk factors, and long-term benefit favours continuation.$x$, 2),
('d0000000-0000-0000-0000-000000000014', 'C', 'Switch dapagliflozin to empagliflozin as it has a more favourable safety profile in acute heart failure', false, 'Ruled out because there is no evidence that switching between SGLT2 inhibitors confers any safety advantage in this context; both agents have evidence for use in HFrEF and there is no indication to switch.', 3),
('d0000000-0000-0000-0000-000000000014', 'D', 'Continue dapagliflozin throughout admission and at discharge, as it is safe and beneficial to maintain during hospitalisation for acute decompensated heart failure', true, 'Correct. SGLT2 inhibitors have been shown to be safe and beneficial even when continued or initiated during hospitalisation for acute decompensated heart failure (e.g. DAPA-ACT HF-TIMI 68, EMPULSE trials support in-hospital initiation), reducing the risk of worsening heart failure events and improving outcomes; there is no indication to withhold it here given stable renal function and potassium.', 4),
('d0000000-0000-0000-0000-000000000014', 'E', 'Hold dapagliflozin until eGFR returns to normal range above 60 mL/min/1.73m2', false, 'Ruled out because SGLT2 inhibitors are licensed and beneficial for heart failure down to an eGFR considerably lower than 58, and this level of renal function does not warrant withholding therapy.', 5),
('d0000000-0000-0000-0000-000000000015', 'A', 'The LMNA mutation has no bearing on management beyond standard heart failure therapy, since his LVEF does not yet meet the standard 35% threshold for ICD implantation', false, 'Ruled out because LMNA cardiomyopathy is a recognised exception where standard LVEF-based ICD thresholds underestimate arrhythmic risk; specific risk stratification tools and lower thresholds for device therapy are used given the disproportionately high risk of sudden death.', 1),
('d0000000-0000-0000-0000-000000000015', 'B', 'Genetic testing results should not influence family screening as dilated cardiomyopathy is not typically heritable', false, 'Ruled out because dilated cardiomyopathy has a significant heritable component (up to 20-35% of cases), and identification of a pathogenic LMNA variant has direct implications for cascade genetic testing and clinical screening of first-degree relatives.', 2),
('d0000000-0000-0000-0000-000000000015', 'C', 'LMNA-associated cardiomyopathy carries a high risk of malignant ventricular arrhythmia and conduction disease disproportionate to the degree of LV impairment, and should prompt consideration of ICD implantation even at only moderately reduced LVEF', true, 'Correct. LMNA cardiomyopathy is well recognised for a high burden of life-threatening ventricular arrhythmia and progressive conduction system disease (AV block) that is disproportionate to the degree of LV systolic dysfunction. Risk calculators specific to LMNA cardiomyopathy exist, and current guidelines support consideration of ICD implantation in these patients at lower LVEF thresholds than standard non-ischaemic cardiomyopathy risk stratification, given the arrhythmic risk profile and family history of sudden death and conduction disease.', 3),
('d0000000-0000-0000-0000-000000000015', 'D', 'He should be reassured that conduction disease is unlikely to develop given his current normal rhythm', false, 'Ruled out because LMNA cardiomyopathy is specifically associated with progressive conduction system disease, including high risk of AV block, and ongoing surveillance (ECG, potentially prolonged monitoring) is required even in the absence of current arrhythmia.', 4),
('d0000000-0000-0000-0000-000000000015', 'E', 'Beta-blocker therapy alone is sufficient to mitigate his sudden cardiac death risk without need for device therapy', false, 'Ruled out because beta-blockade does not adequately mitigate the specific high risk of malignant ventricular arrhythmia and conduction disease seen in LMNA cardiomyopathy; ICD implantation should be actively considered based on validated risk calculators for this specific genetic aetiology.', 5),
('d0000000-0000-0000-0000-000000000016', 'A', 'Start an ACE inhibitor to reduce afterload and improve the outflow gradient', false, 'Ruled out because vasodilators (including ACE inhibitors) can worsen LVOT obstruction in obstructive HCM by reducing afterload and increasing the gradient; they should generally be avoided or used with caution in this context.', 1),
('d0000000-0000-0000-0000-000000000016', 'B', 'Refer for permanent pacemaker implantation as first-line therapy for the outflow obstruction', false, 'Ruled out because pacing is not first-line for LVOT obstruction in HCM; it has a limited, more historical role in selected patients not candidates for other therapies, whereas medical optimisation and septal reduction therapy are the primary evidence-based strategies.', 2),
('d0000000-0000-0000-0000-000000000016', 'C', 'Advise vigorous exercise to improve functional capacity and reduce hypertrophy', false, 'Ruled out because patients with obstructive HCM and significant gradients/symptoms are generally advised to avoid intense/competitive exercise and exertion that provokes symptoms, given the risk of arrhythmia and exacerbation of outflow obstruction.', 3),
('d0000000-0000-0000-0000-000000000016', 'D', 'Start digoxin to improve contractility and cardiac output', false, 'Ruled out because digoxin, as a positive inotrope, would worsen dynamic LVOT obstruction in HCM and is contraindicated in this context.', 4),
('d0000000-0000-0000-0000-000000000016', 'E', 'Add disopyramide or consider uptitrating beta-blockade further, with referral for septal reduction therapy (myectomy or alcohol septal ablation) if symptoms persist despite optimised medical therapy', true, 'Correct. In symptomatic obstructive HCM with significant resting LVOT gradient, initial management is optimisation of negative inotropes (beta-blockers to target dose, addition of disopyramide, or a myosin inhibitor such as mavacamten where available); if symptoms remain refractory to optimised medical therapy, septal reduction therapy (surgical myectomy, or alcohol septal ablation in suitable candidates) is indicated, particularly with significant gradients and associated mitral regurgitation from systolic anterior motion.', 5),
('d0000000-0000-0000-0000-000000000017', 'A', 'Endomyocardial biopsy alone, without further systemic workup, as the single diagnostic test of choice', false, 'Ruled out because although biopsy (cardiac or extracardiac, e.g. fat pad) can confirm amyloid deposition and typing, the recommended pathway starts with non-invasive screening (light chains, SPEP/UPEP with immunofixation, bone scintigraphy) which, in the correct combination, can non-invasively diagnose ATTR amyloidosis without biopsy in many cases; biopsy is reserved for cases where non-invasive criteria are not met or AL amyloidosis needs histological/typing confirmation.', 1),
('d0000000-0000-0000-0000-000000000017', 'B', 'Genetic testing for hypertrophic cardiomyopathy sarcomeric mutations', false, 'Ruled out because the clinical and echocardiographic picture described (restrictive physiology, biatrial enlargement, low ECG voltage relative to wall thickness, systemic features) is characteristic of infiltrative cardiomyopathy (amyloidosis), not sarcomeric HCM, which does not typically cause this combination of findings, particularly the low-voltage ECG pattern.', 2),
('d0000000-0000-0000-0000-000000000017', 'C', 'Serum/urine free light chains and serum protein electrophoresis with immunofixation, alongside technetium-labelled bone scintigraphy (e.g. DPD/PYP scan)', true, $x$Correct. The clinical picture (restrictive physiology, biatrial enlargement, increased wall thickness with a 'sparkling/granular' echo appearance, low ECG voltage disproportionate to wall thickness, and renal involvement/proteinuria) is highly suggestive of cardiac amyloidosis. Investigation should screen for both AL (light chain) amyloidosis, using serum/urine free light chains and serum/urine protein electrophoresis with immunofixation, and ATTR (transthyretin) amyloidosis, using bone scintigraphy (DPD/PYP/HMDP), which shows characteristic cardiac uptake; a combination of these tests (plus cardiac MRI, and biopsy if needed) establishes the diagnosis and subtype, which is critical since treatment differs markedly between AL and ATTR amyloidosis.$x$, 3),
('d0000000-0000-0000-0000-000000000017', 'D', '24-hour Holter monitor as the key diagnostic investigation', false, 'Ruled out because while arrhythmia monitoring may be relevant to overall management, it does not establish the underlying diagnosis of infiltrative cardiomyopathy suggested by this presentation.', 4),
('d0000000-0000-0000-0000-000000000017', 'E', 'Coronary angiography to exclude ischaemic cardiomyopathy as the primary next investigation', false, 'Ruled out because the clinical and echocardiographic picture (restrictive filling, biatrial enlargement, granular sparkling myocardium, low-voltage ECG, systemic renal involvement) points specifically towards infiltrative disease (amyloidosis) rather than an ischaemic aetiology, making amyloid-specific investigations the priority.', 5),
('d0000000-0000-0000-0000-000000000018', 'A', 'Implant a primary prevention ICD immediately regardless of further LVEF trajectory since she is already on optimal medical therapy', false, 'Ruled out because although she meets a threshold LVEF for consideration, continued reassessment is recommended in non-ischaemic cardiomyopathy given the potential for ongoing improvement in LVEF with GDMT, and current evidence (e.g. DANISH trial nuances) supports individualised, sometimes delayed decision-making in non-ischaemic disease rather than immediate implantation in every case.', 1),
('d0000000-0000-0000-0000-000000000018', 'B', 'No ICD is required at any future point since her LVEF has improved from baseline', false, 'Ruled out because her LVEF (34%) remains below the standard 35% threshold associated with primary prevention benefit, and she may still be a candidate for ICD depending on further reassessment; her current trajectory does not yet exclude future need for device therapy.', 2),
('d0000000-0000-0000-0000-000000000018', 'C', 'Proceed directly to CRT-D implantation given her heart failure diagnosis', false, 'Ruled out because CRT is indicated based on QRS duration/morphology criteria (not described here as prolonged), not simply because of an HFrEF diagnosis; there is no information suggesting she meets CRT criteria.', 3),
('d0000000-0000-0000-0000-000000000018', 'D', 'Continue to optimise and reassess LVEF again in a further 3 months before deciding on ICD implantation, as her LVEF remains below the threshold but medical therapy has not yet been given the full duration to show maximal benefit', true, 'Correct. Current guidance recommends reassessing LV function after a period of optimised guideline-directed medical therapy (typically around 3 months, sometimes longer) before committing to primary prevention ICD implantation in non-ischaemic cardiomyopathy, as LVEF can continue to improve with therapy. Her LVEF remains in the range where ICD would typically be considered (below 35%) with NYHA II-III symptoms, but allowing further time for reverse remodelling on optimised quadruple therapy before final ICD decision-making is appropriate and reflects current practice, especially as her LVEF is trending upward.', 4),
('d0000000-0000-0000-0000-000000000018', 'E', 'Stop guideline-directed medical therapy now that LVEF has improved, and monitor off treatment', false, 'Ruled out because improvement in LVEF on GDMT does not mean therapy should be withdrawn; ongoing therapy is required to maintain and further improve function, and withdrawal risks deterioration (as shown in withdrawal studies such as TRED-HF).', 5),
('d0000000-0000-0000-0000-000000000019', 'A', 'Adrenal vein sampling to confirm lateralisation of aldosterone excess to the left adrenal gland', true, 'Correct. In primary hyperaldosteronism with a unilateral adrenal nodule on CT, adrenal vein sampling (AVS) is recommended before proceeding to adrenalectomy, because CT imaging alone is unreliable at distinguishing a functioning adenoma from a non-functioning incidentaloma, and can misguide surgery in a meaningful proportion of patients. AVS confirms whether aldosterone hypersecretion truly lateralises to the side of the visible nodule before committing to unilateral adrenalectomy.', 1),
('d0000000-0000-0000-0000-000000000019', 'B', 'Proceed directly to left laparoscopic adrenalectomy based on the CT findings alone', false, 'Ruled out because CT-identified nodules do not reliably indicate the source of aldosterone excess; proceeding to surgery without AVS risks removing a non-functioning adenoma while leaving the true source of hyperaldosteronism untreated (or missing bilateral disease), particularly relevant given her age and desire for a curative outcome.', 2),
('d0000000-0000-0000-0000-000000000019', 'C', 'Start empirical spironolactone and avoid further investigation of adrenal pathology', false, 'Ruled out because while medical therapy with a mineralocorticoid receptor antagonist is appropriate for bilateral disease or patients unfit/unwilling for surgery, this patient has a unilateral nodule and could potentially be cured surgically; appropriate lateralisation studies should be pursued first rather than defaulting to lifelong medical therapy without investigation.', 3),
('d0000000-0000-0000-0000-000000000019', 'D', 'Repeat the aldosterone-to-renin ratio testing while withdrawing all antihypertensives to confirm the diagnosis', false, 'Ruled out because the diagnosis of primary hyperaldosteronism is already biochemically confirmed (elevated aldosterone, suppressed renin, hypokalaemia); the next step is defining lateralisation, not repeating confirmatory testing, and withdrawing antihypertensives in someone with BP 168/102 would be unsafe.', 4),
('d0000000-0000-0000-0000-000000000019', 'E', 'Arrange genetic testing for familial hyperaldosteronism as the next step before any imaging-guided decision', false, 'Ruled out because genetic testing for familial hyperaldosteronism (e.g. glucocorticoid-remediable aldosteronism) is reserved for specific scenarios such as very young onset, strong family history, or early-onset stroke, not as a routine next step here; the priority is lateralisation of the biochemically confirmed unilateral-appearing disease.', 5),
('d0000000-0000-0000-0000-000000000020', 'A', 'Add spironolactone as the next agent given his elevated cardiovascular risk', false, 'Ruled out because in resistant hypertension algorithms, a diuretic (thiazide-like or loop, depending on renal function) is typically the next step after ACEi/ARB plus CCB and before considering a mineralocorticoid receptor antagonist; spironolactone also carries a higher hyperkalaemia risk in the context of CKD and concurrent ACE inhibitor and SGLT2 inhibitor use, requiring caution and closer monitoring if used at this stage.', 1),
('d0000000-0000-0000-0000-000000000020', 'B', 'Add a thiazide-like diuretic (e.g. indapamide) or a loop diuretic if eGFR is low enough to reduce thiazide efficacy', true, 'Correct. In resistant hypertension with CKD, the standard next step after ACE inhibitor/ARB and calcium channel blocker is to add a diuretic; thiazide-like diuretics remain reasonably effective down to an eGFR around this range, but as renal function declines further, a loop diuretic may be needed for adequate natriuresis and blood pressure control. This is the standard step-up per resistant hypertension algorithms (e.g. NICE), prior to considering additional agents such as spironolactone (guided by potassium level and eGFR) or alpha/beta-blockers.', 2),
('d0000000-0000-0000-0000-000000000020', 'C', 'Stop the ACE inhibitor and switch to an angiotensin receptor blocker, as ACE inhibitors are ineffective in CKD', false, 'Ruled out because ACE inhibitors remain effective and renoprotective in CKD; there is no rationale to switch classes here, as the issue is inadequate combination therapy rather than an ineffective drug class, and switching would not add additional antihypertensive effect.', 3),
('d0000000-0000-0000-0000-000000000020', 'D', 'Add a beta-blocker as the next step in the standard resistant hypertension pathway', false, 'Ruled out because beta-blockers are not the standard next step in resistant hypertension algorithms unless there is a compelling indication (e.g. ischaemic heart disease, heart failure, rate control); diuretics are the conventional next step before beta-blockade or alpha-blockade are considered.', 4),
('d0000000-0000-0000-0000-000000000020', 'E', 'Increase amlodipine beyond standard maximum dose to achieve better control', false, 'Ruled out because amlodipine is already at maximal tolerated/licensed dose; exceeding standard maximum dosing risks increased adverse effects (oedema, hypotension) without an evidence base, and the correct approach is to add a further antihypertensive class rather than exceed dosing limits.', 5),
('d0000000-0000-0000-0000-000000000021', 'A', 'Manage as outpatient with oral labetalol and review in the antenatal clinic in one week', false, 'Ruled out because severe hypertension with multi-organ features (thrombocytopenia, deranged LFTs, epigastric pain, significant proteinuria) requires urgent inpatient management, not outpatient follow-up at this level of severity; delay risks eclampsia, HELLP syndrome progression, or maternal stroke.', 1),
('d0000000-0000-0000-0000-000000000021', 'B', 'Admit for urgent control of blood pressure with an agent such as IV labetalol or oral nifedipine, and initiate magnesium sulphate for seizure prophylaxis given severe features of pre-eclampsia', true, 'Correct. This presentation (severe hypertension ≥160/110, proteinuria, thrombocytopenia, deranged LFTs, epigastric pain) meets criteria for pre-eclampsia with severe features. Priorities are urgent blood pressure control (IV labetalol, oral nifedipine, or IV hydralazine) to reduce the risk of maternal stroke, and magnesium sulphate for seizure prophylaxis given the severity of the picture, alongside close maternal and fetal monitoring and planning for timing of delivery.', 2),
('d0000000-0000-0000-0000-000000000021', 'C', 'Commence low-dose aspirin now as the primary intervention to reduce disease severity', false, 'Ruled out because aspirin is used prophylactically from early pregnancy in women at risk of pre-eclampsia; it has no role in acutely treating established severe pre-eclampsia and would not address the urgent need for blood pressure control and seizure prophylaxis.', 3),
('d0000000-0000-0000-0000-000000000021', 'D', 'Immediate caesarean section regardless of gestational age or maternal/fetal stability', false, 'Ruled out because while delivery is the definitive treatment for pre-eclampsia, the immediate priority is maternal stabilisation (blood pressure control, magnesium sulphate) with a multidisciplinary decision on timing and mode of delivery based on gestation and severity, rather than mandating immediate caesarean regardless of clinical context.', 4),
('d0000000-0000-0000-0000-000000000021', 'E', 'Withhold magnesium sulphate unless she develops a seizure, as prophylactic use is not indicated', false, 'Ruled out because magnesium sulphate is indicated prophylactically in severe pre-eclampsia to reduce the risk of progression to eclampsia, not only after a seizure has occurred; waiting for a seizure to occur before treating is unsafe.', 5),
('d0000000-0000-0000-0000-000000000022', 'A', 'A calcium channel blocker (e.g. amlodipine)', true, 'Correct. For patients of Black African or African-Caribbean family origin without type 2 diabetes, current guidance (e.g. NICE) recommends a calcium channel blocker as first-line therapy, as ACE inhibitors/ARBs tend to be less effective as monotherapy in this population due to typically lower renin levels, and CCBs have robust evidence for efficacy and outcomes in this group.', 1),
('d0000000-0000-0000-0000-000000000022', 'B', 'An ACE inhibitor (e.g. ramipril)', false, 'Ruled out because ACE inhibitors are generally less effective as first-line monotherapy in patients of Black African/African-Caribbean origin without diabetes, due to a tendency towards lower-renin hypertension in this population; current guidance favours calcium channel blockers as first-line in this specific context.', 2),
('d0000000-0000-0000-0000-000000000022', 'C', 'A thiazide-like diuretic (e.g. indapamide) as first-line monotherapy', false, 'Ruled out because although thiazide-like diuretics are an effective option in this population, current first-line guidance specifically recommends a calcium channel blocker before diuretics in patients of Black African/African-Caribbean origin without diabetes.', 3),
('d0000000-0000-0000-0000-000000000022', 'D', 'A beta-blocker (e.g. bisoprolol) as first-line monotherapy', false, 'Ruled out because beta-blockers are not first-line for uncomplicated essential hypertension in current guidelines (reserved for specific compelling indications such as heart failure, ischaemic heart disease, or younger patients with certain features/intolerance to other agents).', 4),
('d0000000-0000-0000-0000-000000000022', 'E', 'An angiotensin receptor blocker (e.g. losartan) as first-line monotherapy', false, 'Ruled out because ARBs, like ACE inhibitors, are generally less effective as first-line monotherapy in this population without diabetes; a calcium channel blocker is preferred as the initial agent.', 5),
('d0000000-0000-0000-0000-000000000023', 'A', 'Beta-blockade alone, started immediately, without need for alpha-blockade', false, 'Ruled out because starting beta-blockade before adequate alpha-blockade in phaeochromocytoma can precipitate a hypertensive crisis due to unopposed alpha-adrenergic vasoconstriction (loss of beta-2 mediated vasodilation while alpha-mediated vasoconstriction continues unchecked).', 1),
('d0000000-0000-0000-0000-000000000023', 'B', 'Beta-blockade first, followed by alpha-blockade once heart rate is controlled', false, 'Ruled out for the same reason: beta-blockade must never precede adequate alpha-blockade in phaeochromocytoma management, due to the risk of a hypertensive crisis from unopposed alpha stimulation.', 2),
('d0000000-0000-0000-0000-000000000023', 'C', 'No pharmacological preparation is needed provided surgery is performed under general anaesthesia by an experienced surgeon', false, 'Ruled out because inadequate preoperative alpha (and subsequently beta) blockade in phaeochromocytoma surgery carries a high risk of intraoperative hypertensive crisis and severe haemodynamic instability during tumour manipulation, regardless of surgical or anaesthetic expertise; pharmacological preparation is essential.', 3),
('d0000000-0000-0000-0000-000000000023', 'D', 'Start an ACE inhibitor as first-line preoperative blood pressure control', false, 'Ruled out because ACE inhibitors are not the standard/recommended preoperative preparation for phaeochromocytoma; alpha-blockade is the established first-line approach to control catecholamine-mediated vasoconstriction prior to surgery.', 4),
('d0000000-0000-0000-0000-000000000023', 'E', 'Alpha-blockade (e.g. phenoxybenzamine or doxazosin) started first, with a beta-blocker added subsequently once alpha-blockade is established, alongside adequate volume/salt repletion', true, 'Correct. Preoperative preparation for phaeochromocytoma requires alpha-blockade first (to control catecholamine-driven vasoconstriction and hypertension), with beta-blockade added only after adequate alpha-blockade is established (typically after several days), to prevent unopposed alpha-adrenergic stimulation which can precipitate a hypertensive crisis. Adequate volume and salt repletion is also important, as patients are often volume-depleted from chronic vasoconstriction, and this reduces the risk of profound hypotension after tumour removal.', 5),
('d0000000-0000-0000-0000-000000000024', 'A', 'Reassurance and antihypertensive therapy alone, with no further intervention required', false, 'Ruled out because significant coarctation of the aorta, especially with a large gradient and collateral formation, carries substantial long-term cardiovascular risk if untreated; definitive intervention is indicated in significant coarctation regardless of current symptom status, not medical therapy alone.', 1),
('d0000000-0000-0000-0000-000000000024', 'B', 'Immediate emergency surgery within 24 hours regardless of further assessment', false, 'Ruled out because although intervention is indicated, this is not an acute emergency requiring surgery within 24 hours in an asymptomatic, haemodynamically stable adult; appropriate specialist assessment and planning (including imaging and consideration of percutaneous versus surgical approach) should occur first.', 2),
('d0000000-0000-0000-0000-000000000024', 'C', 'Referral for definitive intervention (percutaneous stenting or surgical repair) after further assessment, alongside continued blood pressure control', true, 'Correct. This presentation (radio-femoral delay, arm blood pressure discrepancy, significant aortic narrowing beyond the left subclavian artery with rib-notching-associated intercostal collaterals) is classic for adult coarctation of the aorta, likely previously undiagnosed. Significant coarctation, even if the patient is currently asymptomatic other than hypertension, warrants specialist assessment for definitive intervention (percutaneous stenting or surgical repair) given the long-term risks of uncontrolled hypertension, aneurysm formation, aortic dissection, and premature cardiovascular disease if left untreated; blood pressure control is optimised alongside intervention planning.', 3),
('d0000000-0000-0000-0000-000000000024', 'D', 'Genetic testing for Marfan syndrome as the priority before any other action', false, 'Ruled out because while coarctation can be associated with other conditions (e.g. bicuspid aortic valve, Turner syndrome), routine Marfan genetic testing is not the priority next step for an isolated coarctation finding without other syndromic features described; the priority is referral for definitive management of the coarctation itself.', 4),
('d0000000-0000-0000-0000-000000000024', 'E', 'Continue current antihypertensive therapy and repeat imaging in 5 years to monitor progression', false, 'Ruled out because significant coarctation warrants active referral for intervention rather than a prolonged watch-and-wait approach, given ongoing risks of hypertension-related complications, aneurysm, and dissection.', 5),
('d0000000-0000-0000-0000-000000000025', 'A', 'Continue IV antibiotics alone and reassess with repeat echocardiography in 2 weeks', false, 'Ruled out because an abscess in prosthetic valve endocarditis is unlikely to resolve with antibiotics alone and carries high risk of progression (heart block, fistula, valve dehiscence); definitive surgical management is indicated without waiting for interval deterioration.', 1),
('d0000000-0000-0000-0000-000000000025', 'B', 'Defer any surgical intervention until the patient develops heart failure symptoms', false, 'Ruled out because waiting for heart failure to develop before considering surgery ignores an existing class I indication (abscess) for early surgery, and delay increases risk of embolisation, conduction disease, and mortality.', 2),
('d0000000-0000-0000-0000-000000000025', 'C', 'Switch to oral antibiotic therapy once cultures show clearance, avoiding surgery given his current stability', false, 'Ruled out because a paravalvular abscess is a structural, surgical problem that antibiotics (IV or oral) cannot reliably resolve alone; the current haemodynamic stability does not negate the indication for surgery given the destructive local complication.', 3),
('d0000000-0000-0000-0000-000000000025', 'D', 'Urgent surgical referral for valve replacement/debridement in addition to appropriate IV antibiotics, given the paravalvular abscess and prosthetic valve involvement', true, 'Correct. Paravalvular abscess formation in prosthetic valve endocarditis is a class I surgical indication regardless of haemodynamic stability, because it represents locally destructive, uncontrolled infection with high risk of conduction abnormalities, fistula formation, and further valve dehiscence; this requires urgent surgery (debridement and valve replacement) in addition to targeted IV antibiotic therapy, rather than antibiotics alone.', 4),
('d0000000-0000-0000-0000-000000000025', 'E', 'Perform percutaneous aspiration of the abscess as a less invasive alternative to surgery', false, 'Ruled out because percutaneous aspiration is not an established or effective treatment for a paravalvular cardiac abscess; surgical debridement with valve replacement is the standard of care.', 5),
('d0000000-0000-0000-0000-000000000026', 'A', 'Upper GI endoscopy as the priority investigation given the streptococcal species identified', false, 'Ruled out because the recognised association with Streptococcus gallolyticus/bovis is specifically with colorectal pathology, not upper GI tract disease; colonoscopy, not upper endoscopy, is the appropriate targeted investigation.', 1),
('d0000000-0000-0000-0000-000000000026', 'B', 'Dental panoramic radiograph as the priority investigation, given the usual oral source of streptococcal endocarditis', false, 'Ruled out because while oral streptococci (viridans group) are associated with dental sources, S. gallolyticus/bovis specifically has its recognised association with the gastrointestinal (colorectal) tract, making colonoscopy the priority investigation rather than dental imaging.', 2),
('d0000000-0000-0000-0000-000000000026', 'C', 'No further investigation is required once antibiotic treatment is complete', false, 'Ruled out because failing to investigate for underlying colorectal neoplasia in this specific organism would miss a clinically important and well-established association, potentially delaying diagnosis of colorectal cancer.', 3),
('d0000000-0000-0000-0000-000000000026', 'D', 'CT chest to look for an underlying source given possible haematogenous spread from a pulmonary focus', false, 'Ruled out because there is no established primary association between S. gallolyticus/bovis endocarditis and pulmonary pathology; the relevant, evidence-based association is with colorectal neoplasia, directing investigation towards colonoscopy.', 4),
('d0000000-0000-0000-0000-000000000026', 'E', 'Colonoscopy to investigate for underlying colorectal neoplasia', true, 'Correct. Streptococcus gallolyticus (bovis) endocarditis has a well-established association with colorectal neoplasia (adenomas and carcinoma), thought to relate to translocation of the organism across abnormal colonic mucosa. Colonoscopy should be arranged during the same admission (or shortly after) to investigate for an underlying colonic lesion, as identification and treatment of a colorectal malignancy is an important part of overall management in these patients.', 5),
('d0000000-0000-0000-0000-000000000027', 'A', 'Emergency tricuspid valve replacement given the size of the vegetation and evidence of embolisation', false, 'Ruled out because vegetation size and the presence of septic pulmonary emboli alone are not automatic surgical indications in right-sided endocarditis when the patient is haemodynamically stable and responding to antibiotics; surgery is reserved for specific refractory scenarios.', 1),
('d0000000-0000-0000-0000-000000000027', 'B', 'Tricuspid valve repair only, avoiding replacement, as first-line management regardless of clinical response to antibiotics', false, 'Ruled out because surgery of any kind (repair or replacement) is not the first-line approach here; antibiotic therapy is first-line, with surgery reserved for specific indications if the patient fails to respond or develops complications.', 2),
('d0000000-0000-0000-0000-000000000027', 'C', 'Targeted IV antibiotic therapy for an appropriate duration, with surgery reserved for specific indications such as persistent bacteraemia/sepsis despite antibiotics, very large vegetations with recurrent emboli, right heart failure, or difficult-to-treat organisms', true, 'Correct. Right-sided (tricuspid) native valve endocarditis, even with large vegetations and septic pulmonary emboli, is generally managed with targeted IV antibiotic therapy first-line, as it often has a better prognosis than left-sided endocarditis and responds well to antibiotics alone in many cases. Surgery is reserved for specific indications (persistent bacteraemia or sepsis despite appropriate antibiotics, right heart failure, very large vegetations with recurrent pulmonary emboli, or difficult organisms/fungal infection), none of which are yet present in this stable patient.', 3),
('d0000000-0000-0000-0000-000000000027', 'D', 'Oral antibiotics from the outset, given the lower morbidity associated with right-sided endocarditis', false, 'Ruled out because standard management of infective endocarditis, including right-sided disease, is with IV antibiotic therapy for an appropriate prolonged duration; oral-only therapy from the outset is not standard practice for this presentation.', 4),
('d0000000-0000-0000-0000-000000000027', 'E', 'Anticoagulation with therapeutic heparin to prevent further embolic events', false, 'Ruled out because therapeutic anticoagulation is not indicated to prevent septic emboli in infective endocarditis and does not address the underlying infected vegetation; it may increase bleeding risk (e.g. haemorrhagic transformation of septic emboli) without proven benefit.', 5),
('d0000000-0000-0000-0000-000000000028', 'A', 'Antibiotic prophylaxis is not routinely recommended for this dental procedure based on his cardiac history alone', true, 'Correct. Current guidance (including NICE, aligned increasingly with more restrictive international recommendations) does not routinely recommend antibiotic prophylaxis for dental procedures based on underlying cardiac conditions such as a bicuspid aortic valve without prosthetic material or prior endocarditis; the evidence for benefit from routine prophylaxis in this context is limited, and emphasis is instead placed on maintaining good oral hygiene and prompt treatment of any dental infection.', 1),
('d0000000-0000-0000-0000-000000000028', 'B', 'Give amoxicillin prophylaxis 1 hour before the procedure as routine practice for any structural heart disease', false, 'Ruled out because current guidance has moved away from routine antibiotic prophylaxis for dental procedures in patients with structural heart disease who do not have prosthetic valves, a prior history of endocarditis, or specific high-risk congenital heart disease; a bicuspid aortic valve alone does not meet criteria for routine prophylaxis.', 2),
('d0000000-0000-0000-0000-000000000028', 'C', 'Give clindamycin prophylaxis instead of amoxicillin, as this is now preferred in structural heart disease', false, 'Ruled out because the issue is not choice of antibiotic but whether prophylaxis is indicated at all; current guidance does not support routine prophylaxis for this indication and patient group.', 3),
('d0000000-0000-0000-0000-000000000028', 'D', 'Delay the dental procedure until the patient has had a formal cardiology assessment for endocarditis risk', false, 'Ruled out because a bicuspid aortic valve without prosthetic material or prior endocarditis is not considered high enough risk to require delaying routine dental care pending cardiology review; oral hygiene and prompt dental treatment are what is emphasised, not delay.', 4),
('d0000000-0000-0000-0000-000000000028', 'E', 'Administer prophylactic antibiotics only if the patient reports symptoms of active dental infection at the time of the appointment', false, $x$Ruled out because active dental infection would be treated with therapeutic antibiotics for the infection itself, not simply as 'prophylaxis' for endocarditis; this option conflates two different clinical scenarios and does not reflect current guidance for this specific low/moderate-risk patient having elective dental treatment.$x$, 5),
('d0000000-0000-0000-0000-000000000029', 'A', 'Stop antibiotics immediately given the neurological event and reassess in one week', false, 'Ruled out because stopping antibiotics for endocarditis due to an embolic (not haemorrhagic, not treatment-related) stroke is not appropriate; ongoing antimicrobial therapy remains essential to control the underlying infection, and the embolic event itself does not indicate antibiotic failure requiring cessation.', 1),
('d0000000-0000-0000-0000-000000000029', 'B', 'Continue IV antibiotic therapy, and undertake multidisciplinary (cardiology, cardiac surgery, neurology) discussion regarding timing of any valve surgery, generally delaying surgery for a period after a non-haemorrhagic stroke unless another urgent surgical indication exists', true, 'Correct. A non-haemorrhagic embolic stroke during treated endocarditis does not usually mandate immediate cessation of antibiotics or automatic urgent surgery; current guidance suggests that in the absence of coma or major haemorrhage, and where another strong surgical indication (e.g. heart failure, uncontrolled infection, recurrent emboli) is not present, valve surgery can often be delayed for a period (commonly around 4 weeks, individualised) after a non-haemorrhagic stroke to reduce the risk of haemorrhagic transformation and neurological deterioration, guided by multidisciplinary discussion including neuroimaging follow-up.', 2),
('d0000000-0000-0000-0000-000000000029', 'C', 'Proceed to emergency valve surgery within 24 hours regardless of the nature of the stroke', false, 'Ruled out because immediate surgery after a stroke (particularly if there has been any haemorrhagic transformation, which needs to be excluded/monitored) carries increased risk of neurological deterioration; unless there is another urgent indication, surgery is often deliberately delayed after a non-haemorrhagic embolic stroke, guided by multidisciplinary input.', 3),
('d0000000-0000-0000-0000-000000000029', 'D', 'Start therapeutic anticoagulation to prevent further embolic events', false, 'Ruled out because therapeutic anticoagulation is not routinely indicated for prevention of further emboli in native valve endocarditis and can increase the risk of haemorrhagic transformation of an embolic infarct; it is not standard management in this context.', 4),
('d0000000-0000-0000-0000-000000000029', 'E', 'Switch to an oral antibiotic regimen immediately to allow early discharge given the neurological event', false, 'Ruled out because the neurological event does not, by itself, indicate a need to switch to oral therapy or discharge; standard practice remains to complete the appropriate IV antibiotic course while managing the neurological complication and reassessing the timing of any surgical intervention.', 5),
('d0000000-0000-0000-0000-000000000030', 'A', 'Coincidental unrelated degenerative conduction system disease', false, 'Ruled out because the temporal association with active endocarditis and confirmed periannular abscess makes direct infective extension into the conduction system a far more likely and clinically important explanation than an unrelated coincidental process, and this association is well recognised in the literature.', 1),
('d0000000-0000-0000-0000-000000000030', 'B', 'Drug-induced conduction disease from antimicrobial therapy', false, 'Ruled out because while some antimicrobials can rarely cause conduction abnormalities, the clinical context here (documented periannular abscess on echocardiography, close anatomical relationship to the conduction system) points specifically towards direct infective extension as the mechanism.', 2),
('d0000000-0000-0000-0000-000000000030', 'C', 'Autoimmune-mediated myocarditis secondary to the systemic infection', false, 'Ruled out because there is a directly demonstrated structural explanation (periannular abscess abutting the conduction system) that is far more consistent with new AV block in this setting than a presumed autoimmune mechanism.', 3),
('d0000000-0000-0000-0000-000000000030', 'D', 'Direct extension of infection/abscess into the periannular tissue adjacent to the AV conduction system, given the proximity of the AV node to the mitral and aortic valve annuli', true, 'Correct. New conduction abnormalities (including AV block) in the setting of endocarditis, particularly with periannular/perivalvular abscess formation, typically result from direct extension of infection into the adjacent conduction tissue, given the close anatomical relationship between the AV node/proximal conduction system and the aortic and mitral valve annuli. New AV block in this context is a red flag for abscess formation and should prompt urgent further evaluation (e.g. TOE) and consideration of urgent surgery.', 4),
('d0000000-0000-0000-0000-000000000030', 'E', 'Electrolyte disturbance secondary to sepsis as the primary cause', false, 'Ruled out because although electrolyte disturbances can contribute to arrhythmia, the clear anatomical finding of a periannular abscess adjacent to the conduction system is the recognised and most likely explanation for new AV block in active endocarditis, and should prompt urgent evaluation for surgery rather than being attributed simply to electrolytes.', 5),
('d0000000-0000-0000-0000-000000000031', 'A', 'Increase the corticosteroid dose indefinitely and abandon any further tapering attempts', false, 'Ruled out because indefinite escalation/continuation of corticosteroids exposes the patient to significant long-term steroid toxicity; guidelines favour introducing a steroid-sparing agent (such as IL-1 blockade) to allow tapering rather than accepting long-term high-dose steroids.', 1),
('d0000000-0000-0000-0000-000000000031', 'B', 'Consider anakinra (IL-1 receptor antagonist) as an add-on therapy for corticosteroid-dependent, colchicine-resistant recurrent pericarditis', true, 'Correct. In recurrent pericarditis that is corticosteroid-dependent and has failed adequate trials of NSAIDs/colchicine (and failed attempts at steroid tapering), IL-1 blockade with anakinra has trial evidence (e.g. AIRTRIP, RHAPSODY) supporting its use to reduce recurrence and facilitate steroid weaning, and is recommended in this refractory scenario by current guidelines.', 2),
('d0000000-0000-0000-0000-000000000031', 'C', 'Proceed directly to pericardiectomy given the recurrent nature of her disease', false, 'Ruled out because pericardiectomy is reserved for truly refractory cases where medical therapy including IL-1 blockade has failed, or in specific circumstances such as effusive-constrictive disease; it is not the appropriate next step before trialling anakinra in this scenario.', 3),
('d0000000-0000-0000-0000-000000000031', 'D', 'Add long-term high-dose aspirin as an alternative to colchicine, which should be discontinued', false, 'Ruled out because colchicine is a cornerstone of recurrent pericarditis management and reduces recurrence risk; it should not be discontinued in favour of aspirin, and this option does not address the need for escalation to IL-1 blockade in colchicine/steroid-refractory disease.', 4),
('d0000000-0000-0000-0000-000000000031', 'E', 'Arrange cardiac MRI only, with no change to pharmacological therapy at this stage', false, 'Ruled out because while cardiac MRI can help characterise pericardial inflammation, this patient has already demonstrated a refractory clinical course (multiple recurrences, steroid-dependence) that warrants escalation of therapy (IL-1 blockade), not simply further imaging without a treatment change.', 5),
('d0000000-0000-0000-0000-000000000032', 'A', 'Long-term diuretic therapy alone, with no plan for surgical intervention', false, 'Ruled out because diuretics only provide symptomatic relief of venous congestion and do not address the mechanical constriction; in confirmed chronic constrictive pericarditis with significant symptoms, pericardiectomy is the definitive treatment rather than lifelong medical management alone.', 1),
('d0000000-0000-0000-0000-000000000032', 'B', 'Colchicine and high-dose NSAIDs as first-line therapy for this presentation', false, 'Ruled out because anti-inflammatory therapy (NSAIDs, colchicine) is used for acute/inflammatory pericarditis and may have a role in early/transient constriction, but this patient has established chronic constrictive physiology with a clear fibrotic cause (radiotherapy), which is unlikely to respond to anti-inflammatory therapy and requires surgical management.', 2),
('d0000000-0000-0000-0000-000000000032', 'C', 'Urgent pericardiocentesis to relieve the haemodynamic abnormality', false, 'Ruled out because there is no significant pericardial effusion described requiring drainage; the pathology here is pericardial thickening/fibrosis causing constriction, not fluid accumulation causing tamponade, so pericardiocentesis would not address the underlying problem.', 3),
('d0000000-0000-0000-0000-000000000032', 'D', 'Referral for pericardiectomy as the definitive treatment', true, $x$Correct. This presentation (right heart failure signs, Kussmaul's sign, pericardial knock, septal bounce, equalisation of diastolic pressures with dip-and-plateau morphology, thickened pericardium, in a patient with a clear cause such as prior mediastinal radiotherapy) is characteristic of chronic constrictive pericarditis. Once established and symptomatic, particularly with a clear structural/haemodynamic diagnosis, pericardiectomy is the definitive treatment, as medical therapy (diuretics) only provides symptomatic relief without addressing the underlying constrictive physiology.$x$, 4),
('d0000000-0000-0000-0000-000000000032', 'E', 'Cardiac transplantation as the only definitive option given his radiotherapy history', false, 'Ruled out because pericardiectomy, not transplantation, is the definitive treatment for constrictive pericarditis with preserved ventricular systolic function; transplantation is not indicated when the underlying problem is pericardial constriction rather than primary myocardial failure.', 5),
('d0000000-0000-0000-0000-000000000033', 'A', 'Simple repeat pericardiocentesis alone, with removal of the drain immediately after the procedure as before', false, 'Ruled out because repeating the same approach without addressing recurrence risk is likely to result in further tamponade episodes; given this is now a recurrence, a strategy to prevent further reaccumulation (extended drainage or surgical window) is more appropriate.', 1),
('d0000000-0000-0000-0000-000000000033', 'B', 'Urgent pericardiectomy as the definitive treatment for malignant effusion', false, 'Ruled out because pericardiectomy (removal of the pericardium) is a more major surgical undertaking generally reserved for constrictive pericarditis, not the standard approach for recurrent malignant effusion, where a pericardial window or prolonged drainage is the more typical and less invasive strategy.', 2),
('d0000000-0000-0000-0000-000000000033', 'C', 'Initiate high-dose corticosteroids as the primary strategy to prevent reaccumulation', false, 'Ruled out because corticosteroids do not address the underlying mechanism of malignant fluid production in this context and are not standard therapy for prevention of recurrent malignant pericardial effusion; drainage-based strategies and treatment of the underlying cancer are the mainstay.', 3),
('d0000000-0000-0000-0000-000000000033', 'D', 'Observe without further intervention, as recurrent malignant effusions typically resolve spontaneously', false, 'Ruled out because malignant pericardial effusions have a high rate of recurrence and can cause life-threatening tamponade; active intervention to prevent recurrence is required rather than watchful waiting.', 4),
('d0000000-0000-0000-0000-000000000033', 'E', 'Repeat pericardiocentesis with consideration of an extended indwelling pericardial drain or a surgical pericardial window/pericardio-peritoneal shunt to reduce recurrence risk', true, 'Correct. Recurrent malignant pericardial effusion with tamponade after initial pericardiocentesis has a high recurrence rate; options to reduce further recurrence include prolonged/extended catheter drainage, sclerotherapy, or a surgical approach such as a pericardial window (subxiphoid or thoracoscopic) or pericardio-peritoneal shunt, allowing ongoing drainage of fluid and reducing the likelihood of repeat tamponade episodes, alongside treatment of the underlying malignancy where possible.', 5),
('d0000000-0000-0000-0000-000000000034', 'A', 'High-dose corticosteroids as first-line monotherapy', false, 'Ruled out because corticosteroids are not first-line for acute pericarditis; they are generally reserved for cases with a contraindication to NSAIDs/colchicine, connective tissue disease-associated pericarditis, or refractory/recurrent cases, and early corticosteroid use has actually been associated with a higher risk of recurrence.', 1),
('d0000000-0000-0000-0000-000000000034', 'B', 'Broad-spectrum IV antibiotics as first-line therapy given the fever', false, 'Ruled out because this presentation (post-viral illness, typical ECG changes, small effusion) is consistent with viral/idiopathic pericarditis, not bacterial infection; antibiotics are not indicated as first-line therapy without evidence of bacterial pericarditis.', 2),
('d0000000-0000-0000-0000-000000000034', 'C', 'High-dose NSAIDs (e.g. ibuprofen) combined with colchicine, alongside gastroprotection', true, 'Correct. First-line treatment of acute pericarditis (including when there is mild troponin elevation suggesting associated myopericarditis, provided there is no haemodynamic compromise or significant ventricular dysfunction) is a combination of high-dose NSAIDs and colchicine, which together reduce symptom duration and significantly reduce the risk of recurrence compared with NSAID monotherapy; gastroprotection should be co-prescribed given NSAID use.', 3),
('d0000000-0000-0000-0000-000000000034', 'D', 'Urgent pericardiocentesis given the presence of a pericardial effusion', false, 'Ruled out because the effusion described is small with no tamponade features; pericardiocentesis is not required for a small, haemodynamically insignificant effusion and would not be first-line management of the underlying pericarditis.', 4),
('d0000000-0000-0000-0000-000000000034', 'E', 'Colchicine monotherapy, withholding NSAIDs due to the mild troponin rise', false, 'Ruled out because mild troponin elevation reflecting associated myopericarditis (with preserved ventricular function and no haemodynamic compromise) does not contraindicate NSAID use; combination NSAID plus colchicine remains first-line, and NSAIDs should not be withheld simply due to mildly elevated troponin in this context.', 5),
('d0000000-0000-0000-0000-000000000035', 'A', 'Urgent pericardiocentesis under echocardiographic guidance', true, 'Correct. This presentation (hypotension, raised JVP, pulsus paradoxus, tachycardia, and echocardiographic evidence of RV diastolic collapse with a large effusion) confirms cardiac tamponade, a medical emergency. Urgent pericardiocentesis (ideally echo-guided) is required to relieve the haemodynamic compromise; in the post-MI context this may represent free wall rupture/haemopericardium (particularly worth considering given the timing after STEMI), which may additionally require urgent surgical involvement, but immediate drainage is the priority intervention to stabilise the patient.', 1),
('d0000000-0000-0000-0000-000000000035', 'B', 'IV furosemide to reduce circulating volume and relieve congestion', false, 'Ruled out because diuretics reduce preload, which would worsen haemodynamic compromise in tamponade (a preload-dependent state due to external compression); this is dangerous and does not address the underlying mechanical problem.', 2),
('d0000000-0000-0000-0000-000000000035', 'C', 'High-dose NSAIDs and colchicine as for uncomplicated post-MI pericarditis', false, $x$Ruled out because this presentation is tamponade physiology, not simple post-MI (Dressler's-type) pericarditis; anti-inflammatory therapy does not address the acute haemodynamic emergency and pericardiocentesis is required first.$x$, 3),
('d0000000-0000-0000-0000-000000000035', 'D', 'Urgent coronary angiography to reassess stent patency as the priority', false, 'Ruled out because although recurrent ischaemia should always be considered post-MI, the clinical and echocardiographic findings here point specifically to tamponade physiology requiring emergency pericardial drainage as the immediate priority, before other diagnostic workup.', 4),
('d0000000-0000-0000-0000-000000000035', 'E', 'IV fluid bolus alone as definitive management, without pericardiocentesis', false, 'Ruled out because although cautious fluid administration can provide temporary haemodynamic support in tamponade while preparing for definitive treatment, it is not definitive management; urgent pericardiocentesis to relieve the compressive effusion is required.', 5),
('d0000000-0000-0000-0000-000000000036', 'A', 'Start high-dose NSAIDs as first-line therapy, as for viral pericarditis', false, 'Ruled out because NSAIDs are generally avoided or used with caution in patients with significant renal impairment/end-stage renal disease due to further nephrotoxicity risk and limited benefit in uraemic pericarditis, where the underlying driver (inadequate dialysis) should be addressed directly.', 1),
('d0000000-0000-0000-0000-000000000036', 'B', 'Intensify haemodialysis, with close monitoring for progression to tamponade and low threshold for pericardiocentesis if haemodynamic compromise develops', true, 'Correct. Uraemic pericarditis/pericardial effusion related to inadequate dialysis often improves with intensification of dialysis (more frequent or prolonged sessions), which is the appropriate initial management in a patient who has been under-dialysed, provided there is no current overt tamponade. Close monitoring is essential given the early signs of right atrial collapse, with a low threshold to proceed to pericardiocentesis if tamponade develops.', 2),
('d0000000-0000-0000-0000-000000000036', 'C', 'Immediate pericardiocentesis regardless of the absence of current tamponade features', false, 'Ruled out because in the absence of overt haemodynamic compromise, the first step is to intensify dialysis and monitor closely, reserving pericardiocentesis for when tamponade develops or effusion remains large/symptomatic despite adequate dialysis, rather than proceeding immediately in every case.', 3),
('d0000000-0000-0000-0000-000000000036', 'D', 'Start colchicine as first-line therapy for this presentation', false, 'Ruled out because colchicine requires significant dose reduction or avoidance in severe renal impairment due to accumulation and toxicity risk, and it does not address the underlying cause here (inadequate dialysis); intensifying dialysis is the priority intervention.', 4),
('d0000000-0000-0000-0000-000000000036', 'E', 'Reassure and discharge with routine outpatient follow-up given the absence of current tamponade', false, 'Ruled out because a large effusion with early signs of right atrial collapse indicates a real risk of progression to tamponade; this warrants inpatient monitoring and active management (dialysis intensification), not discharge with routine follow-up.', 5),
('d0000000-0000-0000-0000-000000000037', 'A', 'Conservative medical management alone, given his age and comorbidities', false, 'Ruled out because severe symptomatic aortic stenosis has a poor prognosis without intervention (high mortality within 1-2 years), and this patient has been assessed as anatomically suitable for a less invasive transcatheter approach; medical therapy alone is not appropriate when a viable intervention exists and the patient is symptomatic.', 1),
('d0000000-0000-0000-0000-000000000037', 'B', 'Surgical aortic valve replacement as the only appropriate option given his valve gradient', false, 'Ruled out because in a frail, high-surgical-risk patient with favourable anatomy for a transcatheter approach, TAVI is a well-evidenced and often preferred alternative to surgery, not an inferior fallback option; the heart team should weigh surgical risk heavily in this decision, favouring TAVI here.', 2),
('d0000000-0000-0000-0000-000000000037', 'C', 'Transcatheter aortic valve implantation (TAVI) following heart team assessment', true, 'Correct. In elderly patients with severe symptomatic aortic stenosis who are high surgical risk (or intermediate-to-high risk depending on age/frailty), with suitable vascular anatomy, TAVI is an appropriate and now often preferred treatment strategy, offering similar or superior outcomes to surgical aortic valve replacement in these patient groups with lower procedural morbidity, guided by multidisciplinary heart team assessment incorporating frailty, comorbidity, and anatomical suitability.', 3),
('d0000000-0000-0000-0000-000000000037', 'D', 'Balloon aortic valvuloplasty alone as definitive long-term treatment', false, 'Ruled out because balloon valvuloplasty provides only temporary symptomatic relief with high restenosis rates and is not considered definitive treatment for severe aortic stenosis; it is generally reserved as a bridge to definitive therapy (TAVI/SAVR) or for palliation in patients unsuitable for either.', 4),
('d0000000-0000-0000-0000-000000000037', 'E', 'Watchful waiting with reassessment in 6 months, as intervention is not indicated until NYHA class IV symptoms develop', false, 'Ruled out because this patient already has symptomatic severe aortic stenosis (NYHA III), which is itself an indication for intervention; delaying treatment until NYHA IV symptoms develop would expose him to unnecessary risk of sudden death and further decompensation.', 5),
('d0000000-0000-0000-0000-000000000038', 'A', 'Surgical mitral valve replacement as first-line treatment given her symptoms', false, 'Ruled out because with favourable valve morphology, percutaneous balloon valvotomy is preferred as the first-line intervention over surgical replacement, which is reserved for patients with unfavourable anatomy, significant MR, left atrial thrombus, or where valvotomy has failed/is unavailable.', 1),
('d0000000-0000-0000-0000-000000000038', 'B', 'Conservative management with diuretics alone, as intervention is not indicated until NYHA class IV symptoms develop', false, 'Ruled out because symptomatic severe mitral stenosis (NYHA III) with favourable anatomy for a low-risk percutaneous procedure is itself an indication for intervention; delaying until NYHA IV would expose her to unnecessary risk of complications such as atrial fibrillation, pulmonary hypertension, and thromboembolism.', 2),
('d0000000-0000-0000-0000-000000000038', 'C', 'Anticoagulation alone with warfarin, without any valve intervention, since she is in sinus rhythm', false, 'Ruled out because anticoagulation does not address the mechanical obstruction of the stenotic valve causing her symptoms; while anticoagulation may be relevant in specific circumstances (e.g. atrial fibrillation, prior embolism), her fundamental problem requires valve intervention given her symptomatic status and favourable anatomy for valvotomy.', 3),
('d0000000-0000-0000-0000-000000000038', 'D', 'Surgical mitral valve repair, avoiding both valvotomy and replacement', false, 'Ruled out because mitral stenosis due to rheumatic disease with favourable morphology is specifically treated with balloon valvotomy rather than surgical repair, which is more typically used for degenerative mitral regurgitation rather than pure rheumatic stenosis.', 4),
('d0000000-0000-0000-0000-000000000038', 'E', 'Percutaneous balloon mitral valvotomy given favourable valve morphology', true, 'Correct. In symptomatic severe mitral stenosis with favourable valve morphology for balloon valvotomy (pliable leaflets, minimal subvalvular disease, no significant MR, absence of left atrial thrombus), percutaneous balloon mitral valvotomy is the treatment of choice, offering good haemodynamic results with lower procedural risk than surgery in appropriately selected patients.', 5),
('d0000000-0000-0000-0000-000000000039', 'A', 'Referral for mitral valve repair given the LV end-systolic diameter meeting the threshold for intervention despite being asymptomatic', true, 'Correct. In asymptomatic severe primary mitral regurgitation, intervention is indicated when there is evidence of LV dysfunction/dilatation (LV end-systolic diameter ≥40mm, or LVEF ≤60%) even without symptoms, given the progressive risk of irreversible LV dysfunction if surgery is delayed. With a highly likely successful repair (flail P2, degenerative aetiology) at an experienced centre, mitral valve repair is recommended in this scenario rather than watchful waiting.', 1),
('d0000000-0000-0000-0000-000000000039', 'B', 'Continue watchful waiting with 6-monthly echocardiography, as intervention is only indicated once symptoms develop', false, 'Ruled out because current guidelines support intervention in asymptomatic severe primary MR once specific LV size/function thresholds are met (as here, LVESD 42mm), rather than waiting for symptom onset, which would risk progression to irreversible LV dysfunction.', 2),
('d0000000-0000-0000-0000-000000000039', 'C', 'Start ACE inhibitor therapy as definitive management to reduce regurgitant volume, deferring surgery', false, 'Ruled out because medical therapy (vasodilators) has not been shown to alter the natural history of primary degenerative MR or delay the need for surgery in a way that substitutes for timely intervention when structural/functional thresholds are met; surgery (repair) is the appropriate definitive treatment here.', 3),
('d0000000-0000-0000-0000-000000000039', 'D', 'Refer for mitral valve replacement rather than repair, given the severity of regurgitation', false, 'Ruled out because with a flail P2 segment (a classic, highly repairable lesion) at an experienced centre, mitral valve repair is strongly preferred over replacement due to better long-term outcomes, preserved subvalvular apparatus, and avoidance of prosthesis-related complications.', 4),
('d0000000-0000-0000-0000-000000000039', 'E', 'Arrange for percutaneous edge-to-edge mitral valve repair (e.g. MitraClip) as first-line treatment', false, 'Ruled out because in a good surgical candidate with a highly repairable lesion (flail P2), surgical mitral valve repair remains the first-line, gold-standard treatment; percutaneous edge-to-edge repair is generally reserved for patients at high or prohibitive surgical risk.', 5),
('d0000000-0000-0000-0000-000000000040', 'A', 'Continue warfarin unchanged throughout pregnancy without discussion of alternatives', false, $x$Ruled out because continuing warfarin through the first trimester (particularly weeks 6-12) carries a recognised risk of warfarin embryopathy; while continuing warfarin (especially at low dose) is one option, the anticoagulation strategy must be actively discussed and individualised rather than continued 'unchanged without discussion', given the well-recognised trade-offs.$x$, 1),
('d0000000-0000-0000-0000-000000000040', 'B', 'Stop all anticoagulation for the first trimester to eliminate fetal risk', false, 'Ruled out because stopping anticoagulation entirely in a patient with a mechanical valve carries an unacceptably high risk of valve thrombosis and thromboembolic complications, which can be catastrophic for both mother and fetus; some form of anticoagulation must be continued throughout pregnancy.', 2),
('d0000000-0000-0000-0000-000000000040', 'C', 'Switch to a direct oral anticoagulant (e.g. apixaban) for the duration of pregnancy', false, 'Ruled out because DOACs are contraindicated in patients with mechanical heart valves due to demonstrated increased risk of valve thrombosis and thromboembolic events (and are not established as safe in pregnancy); they should not be used in this context at any stage of pregnancy.', 3),
('d0000000-0000-0000-0000-000000000040', 'D', 'Discuss switching to therapeutic-dose low molecular weight heparin (with anti-Xa monitoring) for the first trimester, balancing the risk of warfarin embryopathy against maternal thromboembolic risk, as part of shared decision-making', true, 'Correct. Warfarin crosses the placenta and carries a dose-dependent risk of embryopathy, particularly with exposure between roughly weeks 6-12 of gestation; therapeutic-dose LMWH (with close anti-Xa level monitoring) or unfractionated heparin is an alternative during this period to avoid embryopathy, though this carries a higher risk of valve thrombosis than warfarin, so the decision must be individualised through shared decision-making that discusses the trade-off between fetal and maternal risk, ideally involving a multidisciplinary pregnancy heart team.', 4),
('d0000000-0000-0000-0000-000000000040', 'E', 'Delay any anticoagulation decision until the second trimester, as first-trimester exposure is not a concern', false, 'Ruled out because the period of highest risk for warfarin embryopathy is precisely during the first trimester (approximately weeks 6-12), making this exactly the time when the anticoagulation strategy needs urgent, active discussion and decision-making rather than delay.', 5),
('d0000000-0000-0000-0000-000000000041', 'A', 'Simply restart warfarin at the previous dose and recheck INR in one week with no bridging therapy', false, 'Ruled out because a subtherapeutic INR of 1.4 in a mechanical valve patient represents a significant period of inadequate anticoagulation with real thrombotic risk; waiting a week for the INR to correct with warfarin alone (which has a delayed onset of action) without bridging leaves the patient exposed to unnecessary risk of valve thrombosis.', 1),
('d0000000-0000-0000-0000-000000000041', 'B', 'Give a high loading dose of warfarin to rapidly correct the INR without additional heparin', false, $x$Ruled out because large loading doses of warfarin can cause overshoot and unstable anticoagulation, and warfarin's onset of full anticoagulant effect is delayed regardless of loading dose (due to the half-lives of vitamin K-dependent factors); bridging with heparin is still required to provide immediate protection while therapeutic INR is re-established.$x$, 2),
('d0000000-0000-0000-0000-000000000041', 'C', 'Restart warfarin promptly and commence therapeutic-dose unfractionated or low molecular weight heparin as a bridge until the INR returns to therapeutic range', true, 'Correct. A significantly subtherapeutic INR in a patient with a mechanical valve places them at meaningfully increased risk of valve thrombosis and systemic embolism; the appropriate approach is to restart/optimise warfarin dosing and bridge with a therapeutic-dose parenteral anticoagulant (heparin) until the INR is back within the therapeutic target range, given the ongoing period of inadequate anticoagulation.', 3),
('d0000000-0000-0000-0000-000000000041', 'D', 'No specific action is required since the patient is currently asymptomatic with a normally functioning valve', false, 'Ruled out because asymptomatic status does not eliminate the increased thrombotic risk from a significantly subtherapeutic INR in a mechanical valve patient; proactive correction and bridging is required to prevent a future thrombotic event, not reassurance based on the current absence of symptoms.', 4),
('d0000000-0000-0000-0000-000000000041', 'E', 'Switch permanently to therapeutic-dose low molecular weight heparin instead of resuming warfarin', false, 'Ruled out because long-term anticoagulation for mechanical valves should remain warfarin (a vitamin K antagonist), as heparin/LMWH and DOACs are not appropriate for long-term use in this setting due to inferior efficacy at preventing valve thrombosis; heparin here is used as a temporary bridge only until therapeutic INR is achieved.', 5),
('d0000000-0000-0000-0000-000000000042', 'A', 'Conservative management only, as ASD closure is not beneficial in patients over 60 years of age', false, 'Ruled out because age alone is not a contraindication to ASD closure; benefit has been demonstrated even in older patients with significant shunts and RV volume overload, provided pulmonary vascular resistance is not prohibitively elevated.', 1),
('d0000000-0000-0000-0000-000000000042', 'B', 'Surgical closure is mandatory, as percutaneous device closure is not an option for secundum ASDs', false, 'Ruled out because percutaneous device closure is the preferred, well-established, less invasive approach for secundum ASDs with suitable anatomy (adequate rims), and is not restricted from use based on the information given; surgery is reserved for unsuitable anatomy or other structural indications.', 2),
('d0000000-0000-0000-0000-000000000042', 'C', 'No intervention is indicated, as the calculated pulmonary vascular resistance already indicates irreversible pulmonary vascular disease precluding closure', false, 'Ruled out because a pulmonary vascular resistance of 2.5 Wood units is low and does not indicate significant/irreversible pulmonary vascular disease (thresholds of concern are typically much higher); this patient is haemodynamically suitable for closure, not precluded from it.', 3),
('d0000000-0000-0000-0000-000000000042', 'D', 'Percutaneous device closure of the ASD, given the significant shunt with RV volume overload and low pulmonary vascular resistance', true, 'Correct. A secundum ASD with a significant left-to-right shunt (Qp:Qs >1.5:1) causing right heart volume overload (RV dilatation/dysfunction), in the context of low pulmonary vascular resistance (well below levels indicating irreversible pulmonary vascular disease), is an indication for closure. Percutaneous device closure is preferred where the defect anatomy is suitable, as it avoids the morbidity of surgery, and can improve symptoms and reverse RV remodelling even in older patients.', 4),
('d0000000-0000-0000-0000-000000000042', 'E', 'Pulmonary vasodilator therapy (e.g. a phosphodiesterase-5 inhibitor) as first-line treatment instead of closure', false, 'Ruled out because pulmonary vasodilator therapy is not indicated as a substitute for closure in a patient with low pulmonary vascular resistance and a significant shunt; such therapy is reserved for patients with established pulmonary arterial hypertension where closure may not be appropriate or as an adjunct in borderline cases.', 5),
('d0000000-0000-0000-0000-000000000043', 'A', 'Redo surgical aortic valve replacement as the only appropriate treatment for bioprosthetic failure', false, $x$Ruled out because in a patient assessed as high surgical risk by the heart team, valve-in-valve TAVI is an appropriate, evidence-supported alternative to redo surgery, not an inferior option to be dismissed; the heart team's risk assessment should guide selection towards the less invasive strategy when appropriate.$x$, 1),
('d0000000-0000-0000-0000-000000000043', 'B', 'Balloon valvuloplasty of the failing bioprosthesis as definitive treatment', false, 'Ruled out because balloon valvuloplasty alone provides only limited and typically short-lived improvement in a degenerated bioprosthesis and is not considered definitive management; valve-in-valve TAVI addresses the underlying structural problem more durably.', 2),
('d0000000-0000-0000-0000-000000000043', 'C', 'Conservative management with diuretics only, as intervention is not possible once a bioprosthesis has failed', false, 'Ruled out because intervention (valve-in-valve TAVI) is very much possible and is the appropriate management for a symptomatic, significantly degenerated bioprosthesis in a high-surgical-risk patient; medical therapy alone does not address the mechanical valve failure.', 3),
('d0000000-0000-0000-0000-000000000043', 'D', 'Refer for heart transplantation given the failed bioprosthesis', false, 'Ruled out because this presentation reflects isolated structural valve deterioration with preserved underlying cardiac function otherwise (not end-stage heart failure), which is appropriately managed with valve-in-valve TAVI rather than transplantation.', 4),
('d0000000-0000-0000-0000-000000000043', 'E', 'Valve-in-valve transcatheter aortic valve implantation (ViV-TAVI) within the failing bioprosthesis', true, 'Correct. In patients with structural bioprosthetic valve deterioration causing significant haemodynamic dysfunction who are high risk for redo surgery, valve-in-valve TAVI (deploying a transcatheter valve within the failing surgical bioprosthesis) is an established, less invasive alternative to redo surgical replacement, avoiding the higher risks associated with repeat sternotomy/surgery in this population.', 5),
('d0000000-0000-0000-0000-000000000044', 'A', 'Manage medically with blood pressure control alone, reserving surgery for cases with malperfusion', false, 'Ruled out because type A dissection (ascending aorta involvement) is a surgical emergency regardless of the presence of malperfusion, given the high risk of proximal complications (rupture, tamponade, aortic regurgitation, coronary involvement); medical management alone is the strategy for uncomplicated type B (descending) dissection, not type A.', 1),
('d0000000-0000-0000-0000-000000000044', 'B', 'Immediate blood pressure and heart rate control (e.g. IV labetalol or esmolol) while arranging emergency surgical repair', true, 'Correct. Type A aortic dissection (involving the ascending aorta) is a surgical emergency due to the high risk of complications including aortic rupture, cardiac tamponade, and acute severe aortic regurgitation; immediate medical management focuses on rapid heart rate and blood pressure control (typically with an IV beta-blocker such as labetalol or esmolol, targeting a heart rate around 60 bpm and systolic BP 100-120 mmHg, adding a vasodilator if needed once rate is controlled) while urgent emergency surgical repair is arranged without delay.', 2),
('d0000000-0000-0000-0000-000000000044', 'C', 'Start a vasodilator such as IV hydralazine first, before any heart rate control', false, 'Ruled out because starting a vasodilator before adequate heart rate control can cause reflex tachycardia and increased aortic wall shear stress (dP/dt), potentially propagating the dissection; beta-blockade (rate control) should be established first, with vasodilators added subsequently if needed.', 3),
('d0000000-0000-0000-0000-000000000044', 'D', 'Arrange thrombolysis to manage the associated arterial compromise', false, 'Ruled out because thrombolysis has no role in aortic dissection and would be dangerous, significantly increasing the risk of catastrophic haemorrhage/rupture in a patient who requires emergency surgery.', 4),
('d0000000-0000-0000-0000-000000000044', 'E', 'Delay intervention until connective tissue disease screening is completed', false, 'Ruled out because type A dissection requires emergency surgical intervention without delay; connective tissue disease screening (if relevant) is pursued after acute stabilisation and surgery, not before, given the immediate life-threatening nature of the condition.', 5),
('d0000000-0000-0000-0000-000000000045', 'A', 'Immediate transfer for emergency surgical or endovascular aneurysm repair, with permissive hypotension (avoiding aggressive fluid resuscitation) en route', true, 'Correct. This presentation (known AAA, sudden severe abdominal/back pain, hypotension, pulsatile tender mass) indicates a ruptured abdominal aortic aneurysm, a surgical emergency with high mortality. The priority is immediate transfer for emergency repair (open or endovascular, depending on anatomy and local expertise/availability), with a strategy of permissive hypotension (targeting a systolic BP sufficient to maintain cerebral perfusion, e.g. around 80-100mmHg, avoiding aggressive full-volume fluid resuscitation) to avoid dislodging a stabilising clot and worsening haemorrhage before definitive repair.', 1),
('d0000000-0000-0000-0000-000000000045', 'B', 'Aggressive IV fluid resuscitation to restore normal blood pressure before any transfer for surgery', false, 'Ruled out because aggressive fluid resuscitation aiming for a normal blood pressure in suspected ruptured AAA can dislodge the tamponading clot and worsen haemorrhage, increasing mortality; a permissive hypotension strategy is preferred until definitive haemorrhage control (surgery) is achieved.', 2),
('d0000000-0000-0000-0000-000000000045', 'C', 'CT angiography to confirm the diagnosis before any surgical involvement is contacted', false, 'Ruled out because in a peri-arrest patient with a known AAA and a classic clinical presentation of rupture, immediate surgical/vascular team involvement and transfer for emergency repair should not be delayed for confirmatory imaging when the diagnosis is highly likely on clinical grounds and the patient is critically unstable; imaging (if performed at all in extremis) should not delay life-saving intervention.', 3),
('d0000000-0000-0000-0000-000000000045', 'D', 'Insert bilateral large-bore IV access and delay any intervention until 4 units of cross-matched blood are available', false, 'Ruled out because while obtaining IV access and initiating blood product availability is appropriate as part of resuscitation, this should occur in parallel with, not as a prerequisite delaying, urgent transfer for emergency repair; time is critical in ruptured AAA and transfer/surgical mobilisation should not wait for this.', 4),
('d0000000-0000-0000-0000-000000000045', 'E', 'Manage conservatively with analgesia alone, given his critical condition and high risk of intervention', false, 'Ruled out because although mortality from ruptured AAA repair is significant, immediate surgical intervention still offers the only chance of survival; a decision for palliation would only be appropriate after discussion regarding futility/patient wishes, not as the default initial management of a potentially salvageable rupture.', 5),
('d0000000-0000-0000-0000-000000000046', 'A', 'Start oral anticoagulation with a DOAC and arrange outpatient vascular review within one week', false, 'Ruled out because acute limb ischaemia with sensory/motor compromise is a vascular emergency requiring immediate anticoagulation (IV heparin, for rapid, titratable effect) and urgent, not delayed outpatient, vascular assessment; delay risks irreversible limb ischaemia.', 1),
('d0000000-0000-0000-0000-000000000046', 'B', 'Arrange elective duplex ultrasound in the next available slot to confirm the diagnosis before any treatment', false, 'Ruled out because the clinical diagnosis of acute limb ischaemia with a threatened limb (sensory/motor changes) is time-critical, and treatment (heparin, urgent vascular referral) should not wait for elective imaging; urgent (not elective) imaging may be part of rapid work-up but treatment must be initiated immediately.', 2),
('d0000000-0000-0000-0000-000000000046', 'C', 'Apply a compression bandage and elevate the limb while awaiting routine review', false, 'Ruled out because compression and elevation are inappropriate and potentially harmful in acute limb ischaemia, where the priority is to restore perfusion urgently, not to manage the limb as if it were a venous or lymphatic problem.', 3),
('d0000000-0000-0000-0000-000000000046', 'D', 'Administer high-dose aspirin alone and observe for improvement over the next 24 hours', false, 'Ruled out because aspirin alone is inadequate for this presentation; therapeutic anticoagulation (heparin) and urgent revascularisation are required given the threatened limb with sensory and motor compromise, and observation over 24 hours risks irreversible ischaemic damage.', 4),
('d0000000-0000-0000-0000-000000000046', 'E', 'Immediate IV unfractionated heparin and urgent vascular surgical referral for emergency revascularisation', true, 'Correct. This presentation (sudden onset, known AF source of embolism, absent pulses, sensory and motor changes) indicates acute limb ischaemia, classified as Rutherford grade IIa/IIb (marginally to immediately threatened, given preserved but reduced sensory/motor function) requiring urgent intervention. Immediate anticoagulation with IV unfractionated heparin should be started to prevent proximal clot propagation, alongside urgent vascular surgical referral for emergency revascularisation (embolectomy, thrombolysis, or bypass depending on assessment), as delay risks progression to irreversible ischaemia and limb loss.', 5),
('d0000000-0000-0000-0000-000000000047', 'A', 'Reassure and observe, as revascularisation has already been achieved with TIMI 3 flow', false, 'Ruled out because successful restoration of epicardial flow does not equate to resolution of cardiogenic shock; ongoing severe haemodynamic compromise with end-organ hypoperfusion requires active escalation of supportive therapy, not passive observation.', 1),
('d0000000-0000-0000-0000-000000000047', 'B', 'Administer a large-volume IV fluid bolus as the primary intervention', false, 'Ruled out because in cardiogenic shock with severe LV systolic impairment, aggressive fluid loading risks worsening pulmonary oedema without addressing the primary problem of pump failure; targeted, cautious fluid management alongside inotropic/vasopressor support and consideration of mechanical support is more appropriate.', 2),
('d0000000-0000-0000-0000-000000000047', 'C', 'Start high-dose beta-blockade to reduce myocardial oxygen demand', false, 'Ruled out because beta-blockade would further depress an already severely impaired, shocked myocardium and worsen hypotension; it is contraindicated in acute cardiogenic shock.', 3),
('d0000000-0000-0000-0000-000000000047', 'D', 'Escalate to inotropic/vasopressor support and urgent consideration of mechanical circulatory support (e.g. Impella or intra-aortic balloon pump/ECMO depending on availability and shock severity)', true, 'Correct. This presentation represents cardiogenic shock post-MI (hypotension, hypoperfusion with rising lactate and oliguria, severe LV impairment) despite successful revascularisation. Management includes inotropic and/or vasopressor support (e.g. noradrenaline as first-line vasopressor, potentially with an inotrope such as dobutamine) and, in patients with severe or refractory shock, urgent consideration of mechanical circulatory support (percutaneous ventricular assist device, IABP, or veno-arterial ECMO depending on the clinical picture and local resources) to maintain end-organ perfusion while allowing myocardial recovery.', 4),
('d0000000-0000-0000-0000-000000000047', 'E', 'Proceed to immediate surgical revascularisation (CABG) given ongoing haemodynamic instability', false, 'Ruled out because the culprit vessel has already been successfully treated with PCI (TIMI 3 flow restored); the issue is severe pump failure/cardiogenic shock, which should be managed with pharmacological and mechanical circulatory support rather than further revascularisation procedures.', 5),
('d0000000-0000-0000-0000-000000000048', 'A', 'Therapeutic-dose low molecular weight heparin alone, reserving thrombolysis for cardiac arrest only', false, $x$Ruled out because anticoagulation alone is inadequate for haemodynamically unstable ('massive'/high-risk) PE; thrombolysis is indicated at this stage of shock, not only if the patient progresses to cardiac arrest, since earlier intervention improves outcomes and prevents deterioration to arrest.$x$, 1),
('d0000000-0000-0000-0000-000000000048', 'B', 'Systemic thrombolysis (e.g. alteplase), given haemodynamic instability consistent with high-risk (massive) pulmonary embolism', true, 'Correct. This presentation (hypotension, tachycardia, raised JVP, and CT evidence of RV strain) confirms high-risk (massive) pulmonary embolism, defined by haemodynamic instability. In the absence of major contraindications (recent surgery, active bleeding, intracranial pathology), systemic thrombolysis is the first-line treatment to rapidly reduce clot burden and RV strain, reducing mortality in this life-threatening presentation.', 2),
('d0000000-0000-0000-0000-000000000048', 'C', 'Immediate insertion of an IVC filter as the primary intervention', false, 'Ruled out because an IVC filter does not treat the existing clot burden or reverse RV strain/haemodynamic instability; it has a role in specific circumstances (e.g. absolute contraindication to anticoagulation with ongoing risk) but is not primary therapy for high-risk PE with instability.', 3),
('d0000000-0000-0000-0000-000000000048', 'D', 'Arrange outpatient anticoagulation with a DOAC given his young age and lack of comorbidities', false, 'Ruled out because this patient has haemodynamically unstable, high-risk PE requiring emergency inpatient treatment (thrombolysis), not outpatient management with oral anticoagulation, regardless of age or comorbidity status.', 4),
('d0000000-0000-0000-0000-000000000048', 'E', 'Urgent surgical embolectomy as the first-line treatment ahead of thrombolysis', false, 'Ruled out because systemic thrombolysis is first-line for high-risk PE where there is no contraindication; surgical (or catheter-directed) embolectomy is reserved for patients with thrombolysis contraindicated, thrombolysis failure, or specific centres/circumstances where it is preferred, not as routine first-line therapy.', 5),
('d0000000-0000-0000-0000-000000000049', 'A', 'Postpartum myocardial infarction; she should proceed to emergency CABG', false, 'Ruled out because coronary angiography is normal, excluding an ischaemic/infarction aetiology requiring revascularisation; the clinical and echocardiographic picture instead fits peripartum cardiomyopathy.', 1),
('d0000000-0000-0000-0000-000000000049', 'B', 'Amniotic fluid embolism; management should focus on supportive respiratory care alone with no specific cardiac therapy', false, 'Ruled out because amniotic fluid embolism typically presents acutely during labour/delivery, not 3 weeks postpartum, and does not typically cause this pattern of severe dilated cardiomyopathy with markedly reduced LVEF; the clinical picture here is more consistent with peripartum cardiomyopathy, which has specific additional therapeutic considerations.', 2),
('d0000000-0000-0000-0000-000000000049', 'C', 'Peripartum cardiomyopathy; bromocriptine should be considered in addition to standard heart failure therapy to inhibit prolactin and potentially improve LV recovery', true, 'Correct. New-onset heart failure with severely reduced LVEF in the peripartum period (typically last month of pregnancy to several months postpartum), with no other identifiable cause and normal coronary arteries, is characteristic of peripartum cardiomyopathy. In addition to standard acute heart failure management (diuretics, careful use of ACE inhibitors/ARBs postpartum, beta-blockers, consideration of anticoagulation given the very low EF and hypercoagulable postpartum state), bromocriptine (a dopamine agonist that suppresses prolactin) has evidence supporting its use to potentially enhance myocardial recovery, based on the proposed pathophysiological role of oxidative stress-cleaved prolactin fragments in this condition.', 3),
('d0000000-0000-0000-0000-000000000049', 'D', 'Postpartum thyrotoxicosis-induced heart failure; the priority is urgent antithyroid therapy alone', false, 'Ruled out because there is no thyroid function information suggesting thyrotoxicosis, and this presentation and echocardiographic picture is classic for peripartum cardiomyopathy; antithyroid therapy alone would not be the appropriate primary management.', 4),
('d0000000-0000-0000-0000-000000000049', 'E', 'Normal physiological postpartum fluid overload; conservative management with fluid restriction alone is sufficient', false, 'Ruled out because an LVEF of 22% with severe LV dilatation is a pathological finding of significant cardiomyopathy, not simple physiological fluid overload, and requires active heart failure treatment (and consideration of bromocriptine), not fluid restriction alone.', 5),
('d0000000-0000-0000-0000-000000000050', 'A', 'Targeted temperature management (controlled temperature, avoiding fever) and urgent coronary angiography given the shockable rhythm without an obvious non-cardiac cause', true, 'Correct. Post-resuscitation care for a comatose patient after cardiac arrest with a shockable rhythm includes targeted temperature management (maintaining a controlled temperature, e.g. around 36°C, and actively avoiding fever, which is associated with worse neurological outcomes) and urgent coronary angiography, since a significant proportion of out-of-hospital VF arrests without an obvious non-cardiac cause are due to an acute coronary event, even without diagnostic ST elevation on the post-ROSC ECG.', 1),
('d0000000-0000-0000-0000-000000000050', 'B', 'Immediate extubation and neurological assessment, as he is haemodynamically stable', false, 'Ruled out because a comatose patient (GCS 3) post-arrest requires ongoing airway protection, sedation, and supportive critical care (including consideration of temperature management), not immediate extubation; meaningful neurological assessment is unreliable in the immediate post-arrest period and should be deferred, often for at least 72 hours with appropriate prognostication techniques.', 2),
('d0000000-0000-0000-0000-000000000050', 'C', 'Withhold coronary angiography unless the post-ROSC ECG shows diagnostic ST elevation', false, 'Ruled out because a significant proportion of patients with shockable-rhythm cardiac arrest and no obvious non-cardiac cause have an acute coronary lesion even without ST elevation on the post-ROSC ECG; current guidance supports considering urgent angiography in this population rather than restricting it only to those with overt STEMI changes.', 3),
('d0000000-0000-0000-0000-000000000050', 'D', 'Actively rewarm and maintain normothermia above 38°C to support haemodynamic stability', false, 'Ruled out because fever (hyperthermia) after cardiac arrest is associated with worse neurological outcomes and should be actively avoided, not induced or tolerated; targeted temperature management aims to prevent fever, not promote it.', 4),
('d0000000-0000-0000-0000-000000000050', 'E', 'Early prognostication and discussion of withdrawal of care within the first 12 hours based on the current GCS', false, 'Ruled out because early GCS/neurological findings in the immediate post-arrest period are unreliable for prognostication due to the effects of sedation, temperature management, and evolving hypoxic-ischaemic injury; formal neuroprognostication is generally deferred for at least 72 hours using a multimodal approach.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('d0000000-0000-0000-0000-000000000001', 'Recurrent ST elevation in the same territory after primary PCI should be treated as acute stent thrombosis until proven otherwise and requires emergency repeat angiography.', 1),
('d0000000-0000-0000-0000-000000000001', 'Stent thrombosis carries a high mortality and re-infarction risk; rapid re-establishment of flow via repeat PCI is the priority over pharmacological or non-invasive strategies.', 2),
('d0000000-0000-0000-0000-000000000001', 'A small, non-tamponading pericardial effusion post-MI is common and should not distract from the more immediately life-threatening diagnosis of stent thrombosis when the clinical picture fits.', 3),
('d0000000-0000-0000-0000-000000000002', 'Fondaparinux is preferred in NSTEACS for its favourable bleeding profile but requires supplemental unfractionated heparin cover during PCI to prevent catheter thrombosis.', 1),
('d0000000-0000-0000-0000-000000000002', 'Enoxaparin should be avoided or dose-reduced in significant renal impairment because of drug accumulation and increased bleeding risk; fondaparinux dosing also requires caution/avoidance at very low eGFR.', 2),
('d0000000-0000-0000-0000-000000000002', 'Anticoagulant strategy in ACS should balance ischaemic and bleeding risk, factoring in renal function, planned invasive strategy, and choice of P2Y12 inhibitor.', 3),
('d0000000-0000-0000-0000-000000000003', '12 months of DAPT after ACS with PCI/stenting is the default recommendation, individualised by bleeding versus ischaemic risk (e.g. using scores such as PRECISE-DAPT or DAPT score).', 1),
('d0000000-0000-0000-0000-000000000003', 'Shortened DAPT courses (1-3 months) followed by P2Y12 inhibitor monotherapy are increasingly used in patients identified as high bleeding risk, but are not the default strategy in standard-risk ACS patients.', 2),
('d0000000-0000-0000-0000-000000000003', 'Decisions to extend DAPT beyond 12 months are reserved for patients with high ischaemic risk features and low bleeding risk.', 3),
('d0000000-0000-0000-0000-000000000004', 'Right ventricular infarction should be suspected in inferior STEMI with hypotension, and confirmed with a right-sided ECG (ST elevation in V4R) or echocardiography.', 1),
('d0000000-0000-0000-0000-000000000004', 'Management of RV infarction-related hypotension centres on preload optimisation with IV fluids, and avoidance of nitrates, diuretics, and other preload-reducing agents.', 2),
('d0000000-0000-0000-0000-000000000004', 'Complete heart block complicating inferior STEMI usually reflects AV nodal ischaemia (supplied by the RCA) and is often reversible with reperfusion; temporary pacing bridges the patient until then.', 3),
('d0000000-0000-0000-0000-000000000005', 'In haemodynamically stable STEMI patients with multivessel disease, complete revascularisation of significant non-culprit lesions (immediate or staged) reduces cardiovascular death/MI compared with culprit-only PCI.', 1),
('d0000000-0000-0000-0000-000000000005', 'In cardiogenic shock, the opposite strategy applies: culprit-lesion-only PCI is preferred initially, as immediate multivessel PCI increases risk of death and renal failure (CULPRIT-SHOCK trial).', 2),
('d0000000-0000-0000-0000-000000000005', 'Staged non-culprit PCI is typically planned within a defined window (e.g. during the index admission or up to around 45 days) rather than left indefinitely.', 3),
('d0000000-0000-0000-0000-000000000006', 'Takotsubo cardiomyopathy typically presents with an ACS-like picture (chest pain, ST elevation, troponin rise) but unobstructed coronaries on angiography, often triggered by emotional or physical stress.', 1),
('d0000000-0000-0000-0000-000000000006', 'Characteristic imaging findings are apical ballooning with basal hyperkinesis (though other regional variants exist); management is supportive and mirrors acute heart failure care.', 2),
('d0000000-0000-0000-0000-000000000006', $x$Despite a reputation for being 'benign', Takotsubo carries real risk of acute complications including cardiogenic shock, LVOT obstruction, mural thrombus and arrhythmia, and recurrence is possible.$x$, 3),
('d0000000-0000-0000-0000-000000000007', $x$AV node ablation with permanent pacing ('pace and ablate') is an effective strategy for rate control in permanent AF refractory to pharmacological therapy, particularly when rate-related cardiomyopathy is suspected.$x$, 1),
('d0000000-0000-0000-0000-000000000007', 'In patients with reduced LVEF undergoing AV node ablation, biventricular pacing (CRT) is preferred over standard right ventricular pacing to avoid worsening dyssynchrony/cardiomyopathy from chronic RV pacing.', 2),
('d0000000-0000-0000-0000-000000000007', 'Rate-related (tachycardia-mediated) cardiomyopathy should be considered when LV systolic dysfunction accompanies poorly controlled rapid AF, and can improve significantly once rate control is achieved.', 3),
('d0000000-0000-0000-0000-000000000008', $x$AVNRT classically shows pseudo-R' in V1 and pseudo-S waves in the inferior leads due to near-simultaneous atrial and ventricular activation, and typically terminates with adenosine or vagal manoeuvres.$x$, 1),
('d0000000-0000-0000-0000-000000000008', 'Catheter ablation of the slow pathway is first-line definitive treatment for symptomatic, recurrent AVNRT, offering high cure rates and avoiding long-term antiarrhythmic drug exposure.', 2),
('d0000000-0000-0000-0000-000000000008', 'AV node re-entrant tachycardia occurs in a structurally normal heart in most cases and has an excellent prognosis once treated.', 3),
('d0000000-0000-0000-0000-000000000009', 'Electrical storm is defined as ≥3 episodes of sustained VT/VF or appropriate ICD shocks within a 24-hour period and constitutes a cardiac emergency.', 1),
('d0000000-0000-0000-0000-000000000009', 'Management includes sedation/general anaesthesia to reduce sympathetic drive, optimisation of beta-blockade and antiarrhythmic therapy, correction of reversible triggers (ischaemia, electrolytes), and urgent catheter ablation when refractory to drug therapy.', 2),
('d0000000-0000-0000-0000-000000000009', 'ICD deactivation is never appropriate as a primary strategy for refractory VT storm; the device should remain active while the underlying arrhythmia is treated.', 3),
('d0000000-0000-0000-0000-000000000010', 'DOACs do not require heparin bridging when interrupted for surgery, because of their rapid onset and offset, unlike warfarin.', 1),
('d0000000-0000-0000-0000-000000000010', 'The duration of DOAC interruption before surgery depends on the specific drug, renal function, and the bleeding risk of the procedure — longer interruption for high-bleeding-risk surgery or renal impairment.', 2),
('d0000000-0000-0000-0000-000000000010', 'Anticoagulation is typically resumed 24-48 hours post-operatively once adequate haemostasis is confirmed, again depending on procedural bleeding risk.', 3),
('d0000000-0000-0000-0000-000000000011', 'Brugada syndrome type 1 pattern (coved ST elevation ≥2mm in V1-V2) is diagnostic when spontaneous or fever-induced, and combined with syncope or a family history of sudden death indicates high arrhythmic risk.', 1),
('d0000000-0000-0000-0000-000000000011', 'ICD implantation is the mainstay of therapy for high-risk Brugada syndrome patients (those with syncope of likely arrhythmic origin, aborted cardiac arrest, or a spontaneous type 1 pattern with additional risk factors).', 2),
('d0000000-0000-0000-0000-000000000011', 'Fever can unmask or worsen the Brugada ECG pattern and precipitate arrhythmic events; patients should be advised to treat fever promptly and avoid known precipitant drugs.', 3),
('d0000000-0000-0000-0000-000000000012', 'Class Ic antiarrhythmics (flecainide, propafenone) can convert AF into a slower, more organised atrial flutter that may conduct 1:1 through the AV node, producing a fast, potentially haemodynamically unstable tachycardia.', 1),
('d0000000-0000-0000-0000-000000000012', 'Flecainide should generally be co-administered with an AV nodal blocking agent (beta-blocker or non-dihydropyridine calcium channel blocker) when used for rhythm control, partly to mitigate this risk.', 2),
('d0000000-0000-0000-0000-000000000012', 'Catheter ablation of atrial flutter should be considered in patients who develop this complication, particularly if flecainide is otherwise a useful part of their rhythm-control strategy.', 3),
('d0000000-0000-0000-0000-000000000013', 'CRT is most beneficial in HFrEF patients with sinus rhythm, LBBB morphology, and QRS duration ≥150ms who remain symptomatic despite optimal guideline-directed medical therapy.', 1),
('d0000000-0000-0000-0000-000000000013', 'Ivabradine is indicated for HFrEF patients in sinus rhythm with resting heart rate ≥70bpm despite maximal tolerated beta-blocker dose, not in patients with an already-controlled heart rate.', 2),
('d0000000-0000-0000-0000-000000000013', 'Quadruple therapy for HFrEF comprises an ACE inhibitor/ARB or sacubitril-valsartan, a beta-blocker, a mineralocorticoid receptor antagonist, and an SGLT2 inhibitor; device therapy (CRT/ICD) is layered on top when indicated, not a substitute for medical optimisation.', 3),
('d0000000-0000-0000-0000-000000000014', 'SGLT2 inhibitors can be safely continued (and even started) during hospital admission for acute decompensated heart failure, with evidence of clinical benefit rather than harm.', 1),
('d0000000-0000-0000-0000-000000000014', 'Transient SGLT2 inhibitor interruption may be considered in specific high-risk situations (e.g. severe acute illness, major surgery, risk of ketoacidosis, significant AKI) rather than as routine practice during a heart failure admission.', 2),
('d0000000-0000-0000-0000-000000000014', 'SGLT2 inhibitors remain beneficial and licensed for HFrEF across a wide range of eGFR values, well below the threshold suggested in some of the distractor options.', 3),
('d0000000-0000-0000-0000-000000000015', 'LMNA cardiomyopathy is associated with a disproportionately high risk of malignant ventricular arrhythmia and progressive AV conduction disease relative to the degree of LV systolic impairment.', 1),
('d0000000-0000-0000-0000-000000000015', 'Specific risk calculators exist for LMNA cardiomyopathy and support ICD implantation at lower LVEF thresholds than used for non-ischaemic cardiomyopathy generally, especially with additional risk factors like non-missense mutations, male sex, NSVT, and low LVEF.', 2),
('d0000000-0000-0000-0000-000000000015', 'Identification of a pathogenic variant in a proband should prompt cascade genetic testing and clinical screening in first-degree relatives.', 3),
('d0000000-0000-0000-0000-000000000016', 'Obstructive HCM is managed initially with negative inotropes/agents that reduce contractility and outflow gradient (beta-blockers, disopyramide, non-dihydropyridine calcium channel blockers, or cardiac myosin inhibitors), while vasodilators and positive inotropes should be avoided.', 1),
('d0000000-0000-0000-0000-000000000016', 'Septal reduction therapy (surgical myectomy or alcohol septal ablation) is reserved for patients with significant symptoms and outflow obstruction refractory to optimal medical therapy.', 2),
('d0000000-0000-0000-0000-000000000016', 'Systolic anterior motion of the mitral valve contributing to mitral regurgitation is a mechanistic feature of obstructive HCM and often improves after successful gradient reduction.', 3),
('d0000000-0000-0000-0000-000000000017', 'Cardiac amyloidosis should be suspected with restrictive physiology, biatrial enlargement, increased wall thickness with a granular/sparkling echo texture, and a low-voltage ECG disproportionate to wall thickness (a discordance not seen in hypertrophic cardiomyopathy).', 1),
('d0000000-0000-0000-0000-000000000017', 'Diagnostic workup screens in parallel for AL amyloidosis (serum/urine free light chains, SPEP/UPEP with immunofixation) and ATTR amyloidosis (bone scintigraphy), since management and prognosis differ substantially between subtypes.', 2),
('d0000000-0000-0000-0000-000000000017', 'Extracardiac features such as proteinuria/nephrotic syndrome, carpal tunnel syndrome, and autonomic neuropathy support a diagnosis of systemic amyloidosis with cardiac involvement.', 3),
('d0000000-0000-0000-0000-000000000018', 'In non-ischaemic cardiomyopathy, LV function should be reassessed after an adequate trial of optimised guideline-directed medical therapy (commonly around 3 months or more) before finalising the decision on primary prevention ICD implantation, since LVEF can improve substantially.', 1),
('d0000000-0000-0000-0000-000000000018', 'Primary prevention ICD implantation is generally considered for LVEF ≤35% with NYHA II-III symptoms despite optimal medical therapy, but the evidence base and guideline recommendations for non-ischaemic cardiomyopathy specifically emphasise individualised timing.', 2),
('d0000000-0000-0000-0000-000000000018', 'Even with LVEF improvement, guideline-directed medical therapy should generally be continued indefinitely rather than withdrawn, as withdrawal risks relapse of cardiomyopathy.', 3),
('d0000000-0000-0000-0000-000000000019', 'In primary hyperaldosteronism with a unilateral adrenal nodule on CT, adrenal vein sampling is recommended prior to surgery because CT has limited accuracy in identifying the true functional source of aldosterone excess.', 1),
('d0000000-0000-0000-0000-000000000019', 'Confirmed unilateral aldosterone-producing adenoma (by AVS) is treated with unilateral adrenalectomy, often curing or substantially improving the hypertension and hypokalaemia; bilateral disease is managed medically with a mineralocorticoid receptor antagonist.', 2),
('d0000000-0000-0000-0000-000000000019', 'Resistant hypertension with hypokalaemia should prompt screening for primary hyperaldosteronism using the aldosterone-to-renin ratio, ideally after correcting confounding factors (e.g. interfering medications, hypokalaemia itself).', 3),
('d0000000-0000-0000-0000-000000000020', 'In resistant hypertension management (per NICE-style algorithms), after an ACE inhibitor/ARB combined with a calcium channel blocker, the next step is typically a diuretic (thiazide-like if eGFR is adequate, loop diuretic if renal function is more significantly impaired).', 1),
('d0000000-0000-0000-0000-000000000020', $x$Spironolactone is considered a 'fourth-line' option in resistant hypertension, particularly effective when renin is suppressed/aldosterone contribution is suspected, but requires careful potassium and renal function monitoring, especially alongside ACE inhibitors and SGLT2 inhibitors.$x$, 2),
('d0000000-0000-0000-0000-000000000020', 'SGLT2 inhibitors provide modest additional blood pressure lowering alongside their renal and cardiovascular protective effects, but do not replace the need for a structured antihypertensive escalation pathway.', 3),
('d0000000-0000-0000-0000-000000000021', 'Pre-eclampsia with severe features (severe hypertension, and/or significant proteinuria with additional features such as thrombocytopenia, deranged LFTs, renal impairment, epigastric pain, visual disturbance, or headache) requires urgent inpatient management.', 1),
('d0000000-0000-0000-0000-000000000021', 'Magnesium sulphate is used for seizure prophylaxis in severe pre-eclampsia and for treatment of eclamptic seizures, and reduces the risk of progression to eclampsia.', 2),
('d0000000-0000-0000-0000-000000000021', 'Definitive treatment of pre-eclampsia is delivery of the placenta, but timing is balanced against gestational age and maternal/fetal stability, with acute stabilisation prioritised first.', 3),
('d0000000-0000-0000-0000-000000000022', 'Current UK guidance recommends calcium channel blockers as first-line antihypertensive therapy in patients of Black African or African-Caribbean family origin without type 2 diabetes, reflecting typically lower-renin physiology and reduced ACE inhibitor/ARB monotherapy efficacy in this group.', 1),
('d0000000-0000-0000-0000-000000000022', 'In patients with type 2 diabetes (regardless of ethnicity) or younger patients without African/Caribbean family origin, an ACE inhibitor or ARB is generally preferred as first-line therapy.', 2),
('d0000000-0000-0000-0000-000000000022', 'Beta-blockers are not first-line for uncomplicated hypertension but remain appropriate when there is another compelling indication.', 3),
('d0000000-0000-0000-0000-000000000023', 'Preoperative management of phaeochromocytoma requires alpha-blockade before beta-blockade, to avoid a hypertensive crisis from unopposed alpha-adrenergic vasoconstriction.', 1),
('d0000000-0000-0000-0000-000000000023', 'Adequate volume and salt repletion prior to surgery helps prevent profound hypotension after tumour removal, once the catecholamine surge is eliminated.', 2),
('d0000000-0000-0000-0000-000000000023', 'Phaeochromocytoma should be considered in patients with paroxysmal symptoms of headache, palpitations, and sweating with episodic severe hypertension, confirmed biochemically with plasma or urinary metanephrines.', 3),
('d0000000-0000-0000-0000-000000000024', 'Adult coarctation of the aorta should be suspected with hypertension, radio-femoral delay, arm blood pressure discrepancy, and can be associated with intercostal artery collaterals (classically causing rib notching on chest X-ray).', 1),
('d0000000-0000-0000-0000-000000000024', 'Definitive treatment (percutaneous stenting or surgical repair) is generally recommended for significant coarctation to reduce long-term risks of hypertension, aneurysm formation, and aortic dissection, even in patients who are otherwise asymptomatic.', 2),
('d0000000-0000-0000-0000-000000000024', 'Coarctation is associated with bicuspid aortic valve and other conditions (e.g. Turner syndrome); associated structural abnormalities should be assessed for as part of the overall work-up.', 3),
('d0000000-0000-0000-0000-000000000025', 'Paravalvular abscess, fistula formation, and valve dehiscence in infective endocarditis are class I indications for urgent surgery regardless of current haemodynamic status, due to high risk of rapid deterioration and conduction disease.', 1),
('d0000000-0000-0000-0000-000000000025', 'Prosthetic valve endocarditis, particularly with Staphylococcus aureus and structural complications, carries a worse prognosis than native valve endocarditis and a lower threshold for surgical intervention.', 2),
('d0000000-0000-0000-0000-000000000025', 'Surgery in endocarditis is combined with, not a replacement for, an appropriate prolonged course of targeted IV antibiotic therapy.', 3),
('d0000000-0000-0000-0000-000000000026', 'Streptococcus gallolyticus (bovis) endocarditis is strongly associated with underlying colorectal neoplasia (adenomas or carcinoma), and colonoscopy should be arranged as part of the diagnostic work-up.', 1),
('d0000000-0000-0000-0000-000000000026', 'This association reflects an important general principle in endocarditis management: the causative organism can point towards an occult source or underlying pathology requiring separate investigation and treatment.', 2),
('d0000000-0000-0000-0000-000000000026', $x$Identification of colorectal pathology in this context has direct implications for the patient's oncological management, in addition to treatment of the endocarditis itself.$x$, 3),
('d0000000-0000-0000-0000-000000000027', 'Right-sided (tricuspid) native valve endocarditis generally has a better prognosis than left-sided disease and is typically managed with antibiotics alone unless specific surgical indications develop.', 1),
('d0000000-0000-0000-0000-000000000027', 'Surgical indications in right-sided endocarditis include persistent bacteraemia/sepsis despite appropriate antibiotics, right heart failure, very large vegetations with recurrent pulmonary emboli, or difficult-to-treat organisms (e.g. fungal).', 2),
('d0000000-0000-0000-0000-000000000027', 'Septic pulmonary emboli with cavitating nodules on imaging are a recognised complication of right-sided endocarditis and do not, by themselves, mandate surgery.', 3),
('d0000000-0000-0000-0000-000000000028', 'Current guidance does not recommend routine antibiotic prophylaxis for dental procedures based on underlying structural heart disease alone (e.g. bicuspid aortic valve without prosthetic material or prior endocarditis).', 1),
('d0000000-0000-0000-0000-000000000028', 'Antibiotic prophylaxis is generally reserved for the highest-risk groups (e.g. prosthetic valves/material, prior infective endocarditis, certain complex congenital heart disease) as per specific national/international recommendations, which vary slightly between guideline bodies.', 2),
('d0000000-0000-0000-0000-000000000028', 'Maintaining good oral hygiene and prompt treatment of dental infection is emphasised as more important than antibiotic prophylaxis in reducing endocarditis risk for most patients with structural heart disease.', 3),
('d0000000-0000-0000-0000-000000000029', 'A non-haemorrhagic embolic stroke during treated endocarditis generally does not mandate stopping antibiotics or emergency surgery; timing of any indicated valve surgery is individualised via multidisciplinary discussion, often delayed for a period to reduce risk of haemorrhagic transformation.', 1),
('d0000000-0000-0000-0000-000000000029', 'Surgical indications in endocarditis (heart failure, uncontrolled infection/abscess, recurrent emboli despite antibiotics, certain high-risk organisms) are assessed independently of, but alongside, any neurological event.', 2),
('d0000000-0000-0000-0000-000000000029', 'Anticoagulation is not routinely used to prevent embolic events in native valve endocarditis and can increase bleeding risk, particularly after a recent embolic stroke.', 3),
('d0000000-0000-0000-0000-000000000030', 'New atrioventricular block during active endocarditis is a red flag for periannular/perivalvular abscess extension into the adjacent conduction system and should prompt urgent imaging (TOE) if not already performed.', 1),
('d0000000-0000-0000-0000-000000000030', 'The AV node and proximal conduction system lie in close anatomical proximity to the mitral and aortic valve annuli, explaining why annular abscesses frequently cause conduction disturbances.', 2),
('d0000000-0000-0000-0000-000000000030', 'New conduction abnormalities combined with an abscess are a recognised indication for urgent surgical intervention in infective endocarditis, given the risk of further destructive local spread and progression to complete heart block.', 3),
('d0000000-0000-0000-0000-000000000031', 'Recurrent pericarditis refractory to NSAIDs/colchicine and corticosteroid-dependent should prompt consideration of IL-1 receptor antagonism (anakinra), which has trial evidence for reducing recurrence and facilitating steroid tapering.', 1),
('d0000000-0000-0000-0000-000000000031', 'Colchicine is a cornerstone of both first presentations and recurrent pericarditis, reducing recurrence risk, and should generally be continued rather than substituted.', 2),
('d0000000-0000-0000-0000-000000000031', 'Pericardiectomy is reserved for genuinely refractory recurrent pericarditis unresponsive to medical therapy including biologic agents, given its more invasive nature.', 3),
('d0000000-0000-0000-0000-000000000032', $x$Constrictive pericarditis presents with signs of right heart failure, Kussmaul's sign, a pericardial knock, and characteristic haemodynamic findings (equalisation of diastolic pressures, dip-and-plateau/square root sign, ventricular interdependence with septal bounce).$x$, 1),
('d0000000-0000-0000-0000-000000000032', 'Prior mediastinal radiotherapy is a well-recognised cause of constrictive pericarditis, often presenting years after treatment.', 2),
('d0000000-0000-0000-0000-000000000032', 'Pericardiectomy is the definitive treatment for chronic, symptomatic constrictive pericarditis, as medical therapy alone does not resolve the mechanical constriction.', 3),
('d0000000-0000-0000-0000-000000000033', 'Recurrent malignant pericardial effusion has a high risk of further tamponade; strategies to reduce recurrence include extended/prolonged catheter drainage, pericardial sclerotherapy, or a surgical pericardial window.', 1),
('d0000000-0000-0000-0000-000000000033', 'A pericardial window (subxiphoid or thoracoscopic) creates a persistent communication allowing ongoing drainage into the pleural or peritoneal space, reducing the likelihood of recurrent tamponade.', 2),
('d0000000-0000-0000-0000-000000000033', 'Management of malignant pericardial effusion should also address the underlying malignancy where feasible, as systemic disease control can reduce further fluid accumulation.', 3),
('d0000000-0000-0000-0000-000000000034', 'First-line therapy for acute pericarditis is combination NSAID plus colchicine, which reduces both symptom duration and recurrence risk compared with NSAID monotherapy.', 1),
('d0000000-0000-0000-0000-000000000034', 'Mild troponin elevation in pericarditis (myopericarditis) with preserved ventricular function and no haemodynamic compromise does not change first-line management or preclude NSAID use, but does warrant activity restriction and follow-up.', 2),
('d0000000-0000-0000-0000-000000000034', 'Corticosteroids are avoided as first-line therapy in acute pericarditis due to an association with increased recurrence risk, and are reserved for specific situations (NSAID/colchicine contraindication, connective tissue disease, refractory cases).', 3),
('d0000000-0000-0000-0000-000000000035', 'Cardiac tamponade presents with hypotension, raised JVP, tachycardia, pulsus paradoxus, and echocardiographic evidence of chamber collapse (typically RV diastolic collapse, RA systolic collapse); it is a medical emergency requiring urgent pericardial drainage.', 1),
('d0000000-0000-0000-0000-000000000035', 'Post-MI pericardial effusion with tamponade physiology should raise concern for free wall rupture/haemopericardium, particularly in the first days after STEMI, and may require urgent surgical involvement in addition to pericardiocentesis.', 2),
('d0000000-0000-0000-0000-000000000035', 'Diuretics and other preload-reducing measures should be avoided in tamponade, as cardiac output is critically dependent on adequate venous return/preload in this compressive state.', 3),
('d0000000-0000-0000-0000-000000000036', 'Uraemic pericarditis/pericardial effusion is often related to inadequate dialysis and characteristically improves with intensification of dialysis therapy.', 1),
('d0000000-0000-0000-0000-000000000036', 'NSAIDs and colchicine require caution or are relatively contraindicated in significant renal impairment, making them less suitable first-line options in this population compared with addressing the underlying uraemia.', 2),
('d0000000-0000-0000-0000-000000000036', 'Early echocardiographic signs of chamber collapse (e.g. right atrial diastolic collapse) indicate impending tamponade physiology and warrant close monitoring with a low threshold for pericardiocentesis, even before overt clinical tamponade is present.', 3),
('d0000000-0000-0000-0000-000000000037', 'TAVI is an appropriate treatment strategy for severe symptomatic aortic stenosis in patients at intermediate-to-high surgical risk (and increasingly considered across a broader risk spectrum), guided by multidisciplinary heart team assessment of frailty, comorbidity, and anatomical suitability.', 1),
('d0000000-0000-0000-0000-000000000037', 'Symptomatic severe aortic stenosis carries a poor prognosis without intervention and is itself an indication for valve replacement, regardless of NYHA class beyond mild symptoms.', 2),
('d0000000-0000-0000-0000-000000000037', 'Balloon aortic valvuloplasty has a limited, mainly bridging or palliative role due to high rates of restenosis, and is not a substitute for definitive valve replacement.', 3),
('d0000000-0000-0000-0000-000000000038', 'Percutaneous balloon mitral valvotomy is the treatment of choice for symptomatic severe mitral stenosis with favourable valve morphology (pliable leaflets, minimal subvalvular disease, absent significant MR, no left atrial thrombus).', 1),
('d0000000-0000-0000-0000-000000000038', 'Unfavourable valve morphology, significant mitral regurgitation, or left atrial thrombus are indications favouring surgical management (valve replacement) over percutaneous valvotomy.', 2),
('d0000000-0000-0000-0000-000000000038', 'Symptomatic severe mitral stenosis is an indication for intervention regardless of exact NYHA class beyond mild symptoms, particularly when a low-risk percutaneous option is available.', 3),
('d0000000-0000-0000-0000-000000000039', 'In asymptomatic severe primary mitral regurgitation, intervention is recommended once LV dilatation/dysfunction develops (e.g. LVESD ≥40mm or LVEF ≤60%), rather than waiting for symptoms, to avoid irreversible LV impairment.', 1),
('d0000000-0000-0000-0000-000000000039', 'Mitral valve repair (rather than replacement) is strongly preferred when feasible, particularly for degenerative disease with favourable lesions such as an isolated flail P2 segment, due to superior long-term outcomes.', 2),
('d0000000-0000-0000-0000-000000000039', 'Percutaneous edge-to-edge repair (MitraClip) is generally reserved for patients at high or prohibitive surgical risk, not as a first-line alternative to surgical repair in good surgical candidates.', 3),
('d0000000-0000-0000-0000-000000000040', 'Warfarin embryopathy risk is dose-dependent and concentrated in the first trimester (roughly weeks 6-12 of gestation); alternative strategies during this window include therapeutic LMWH with anti-Xa monitoring or unfractionated heparin.', 1),
('d0000000-0000-0000-0000-000000000040', 'Anticoagulation strategy for mechanical valves in pregnancy involves balancing maternal thromboembolic risk (highest with heparin-based regimens, especially if poorly monitored) against fetal risk (highest with warfarin, especially at higher doses), and should be individualised with multidisciplinary input.', 2),
('d0000000-0000-0000-0000-000000000040', 'DOACs are contraindicated in patients with mechanical heart valves at any time due to increased thrombotic risk demonstrated in trials, independent of pregnancy status.', 3),
('d0000000-0000-0000-0000-000000000041', 'A significantly subtherapeutic INR in a patient with a mechanical heart valve requires prompt correction, generally with bridging therapeutic-dose heparin, given the meaningfully increased risk of valve thrombosis during periods of inadequate anticoagulation.', 1),
('d0000000-0000-0000-0000-000000000041', 'Long-term anticoagulation for mechanical valves should remain a vitamin K antagonist (warfarin); heparin is used only as short-term bridging when the INR is subtherapeutic or during temporary interruption.', 2),
('d0000000-0000-0000-0000-000000000041', 'Even asymptomatic patients with a subtherapeutic INR and normally functioning valve on echocardiography still require active correction, as thrombotic risk accrues from the period of inadequate anticoagulation itself.', 3),
('d0000000-0000-0000-0000-000000000042', 'Secundum ASD with a significant shunt (Qp:Qs typically >1.5:1) causing right heart volume overload is an indication for closure, provided pulmonary vascular resistance is not prohibitively elevated.', 1),
('d0000000-0000-0000-0000-000000000042', 'Percutaneous device closure is preferred over surgery for secundum ASDs with suitable defect anatomy, given lower procedural morbidity.', 2),
('d0000000-0000-0000-0000-000000000042', 'Age alone should not preclude ASD closure when there is demonstrable haemodynamic benefit (RV volume overload) and favourable pulmonary vascular resistance.', 3),
('d0000000-0000-0000-0000-000000000043', 'Valve-in-valve TAVI is an established treatment for structural deterioration of a surgical bioprosthetic aortic valve in patients at high risk for redo surgical replacement, avoiding the additional risks of repeat sternotomy.', 1),
('d0000000-0000-0000-0000-000000000043', 'Structural valve deterioration should be suspected with a significant rise in transprosthetic gradient over time on serial echocardiography, often supported by CT assessment of leaflet mobility/calcification.', 2),
('d0000000-0000-0000-0000-000000000043', 'Heart team assessment of surgical risk is central to choosing between redo surgery and a transcatheter valve-in-valve approach for failing bioprostheses.', 3),
('d0000000-0000-0000-0000-000000000044', 'Type A aortic dissection (involving the ascending aorta) is a surgical emergency requiring urgent repair, due to high risk of rupture, tamponade, acute aortic regurgitation, and coronary malperfusion.', 1),
('d0000000-0000-0000-0000-000000000044', 'Initial medical management targets heart rate control first (IV beta-blocker) before blood pressure/vasodilator therapy, to reduce aortic wall shear stress and avoid reflex tachycardia from vasodilation alone.', 2),
('d0000000-0000-0000-0000-000000000044', 'Uncomplicated type B (descending) aortic dissection is generally managed medically first-line, in contrast to type A, which always mandates emergency surgery.', 3),
('d0000000-0000-0000-0000-000000000045', 'Ruptured AAA is a surgical emergency; immediate transfer for repair (open or endovascular) is the priority, with permissive hypotension used en route to avoid clot disruption and worsening haemorrhage.', 1),
('d0000000-0000-0000-0000-000000000045', 'Aggressive fluid resuscitation to a normal blood pressure before haemorrhage control is achieved is associated with worse outcomes in ruptured aneurysm/major haemorrhage generally.', 2),
('d0000000-0000-0000-0000-000000000045', 'Diagnostic imaging should not delay definitive treatment in a haemodynamically unstable patient with a classic clinical presentation of rupture and a known aneurysm.', 3),
('d0000000-0000-0000-0000-000000000046', 'Acute limb ischaemia with sensory and/or motor deficit indicates a threatened limb requiring emergency anticoagulation (IV heparin) and urgent vascular surgical intervention, not delayed or outpatient management.', 1),
('d0000000-0000-0000-0000-000000000046', 'Atrial fibrillation without anticoagulation is a common source of embolic acute limb ischaemia, and identifying the underlying cause is important for both acute and long-term management once the limb is addressed.', 2),
('d0000000-0000-0000-0000-000000000046', 'The Rutherford classification (based on sensory/motor findings and Doppler signals) helps stratify urgency and guide the choice between embolectomy, thrombolysis, or primary amputation in acute limb ischaemia.', 3),
('d0000000-0000-0000-0000-000000000047', 'Cardiogenic shock is defined by hypotension with evidence of end-organ hypoperfusion (oliguria, rising lactate, cool peripheries, altered mentation), which can persist despite technically successful revascularisation due to severe myocardial stunning/dysfunction.', 1),
('d0000000-0000-0000-0000-000000000047', 'Management escalates from vasopressor/inotropic support to mechanical circulatory support (IABP, percutaneous VAD, or ECMO) in refractory cases, aiming to support the circulation while allowing potential myocardial recovery.', 2),
('d0000000-0000-0000-0000-000000000047', 'Aggressive fluid resuscitation and beta-blockade are generally avoided in cardiogenic shock with severe LV impairment, as they can worsen pulmonary congestion or further depress cardiac output respectively.', 3),
('d0000000-0000-0000-0000-000000000048', $x$High-risk ('massive') pulmonary embolism is defined by haemodynamic instability (persistent hypotension, shock) and is a life-threatening emergency requiring rapid reduction of clot burden.$x$, 1),
('d0000000-0000-0000-0000-000000000048', 'Systemic thrombolysis is first-line treatment for high-risk PE without major contraindications, given evidence of reduced mortality compared with anticoagulation alone in this group.', 2),
('d0000000-0000-0000-0000-000000000048', 'Surgical or catheter-directed embolectomy is reserved for patients with contraindications to thrombolysis, failed thrombolysis, or in specialist centres, rather than as routine first-line therapy.', 3),
('d0000000-0000-0000-0000-000000000049', 'Peripartum cardiomyopathy presents with new heart failure and reduced LVEF towards the end of pregnancy or in the months following delivery, with no other identifiable cause, and requires exclusion of other causes such as ischaemia.', 1),
('d0000000-0000-0000-0000-000000000049', 'Bromocriptine, which suppresses prolactin, has trial evidence supporting its use in addition to standard heart failure therapy to potentially improve myocardial recovery in peripartum cardiomyopathy.', 2),
('d0000000-0000-0000-0000-000000000049', 'Anticoagulation should be considered in peripartum cardiomyopathy with very low LVEF, given the additional hypercoagulable state of the postpartum period and increased risk of LV thrombus formation.', 3),
('d0000000-0000-0000-0000-000000000050', 'Targeted temperature management (maintaining a controlled temperature and preventing fever) is a key component of post-cardiac arrest care to help optimise neurological outcomes.', 1),
('d0000000-0000-0000-0000-000000000050', 'Urgent coronary angiography should be considered in comatose survivors of shockable-rhythm cardiac arrest without an obvious non-cardiac cause, even in the absence of diagnostic ST elevation on the post-ROSC ECG.', 2),
('d0000000-0000-0000-0000-000000000050', 'Formal neurological prognostication after cardiac arrest should be delayed (typically at least 72 hours) and based on a multimodal assessment, as early clinical findings are unreliable, particularly in sedated or temperature-managed patients.', 3);
